// ---------- Tunables ----------

/// Maximum number of clock ticks emitted in one demand-driven active burst.
///
/// A single tick should normally be enough after a commit because commit
/// handlers first raise the local clock to `ts_final`; the extra ticks cover
/// crossed wakeups and delayed peer observations without returning to the old
/// always-on heartbeat behavior.
const CLOCK_TICK_ACTIVE_BURST_TICKS: usize = 3;
const CLOCK_TICK_BURST_COOLDOWN_MULTIPLIER: u32 = 4;
const HEAD_EVIDENCE_RETRY_MAX_MULTIPLIER: u32 = 64;
pub(super) const STRICT_REPLICATION_SLOW_STAGE: Duration = Duration::from_secs(1);
const STRICT_DELIVERY_BLOCKED_LOG_INTERVAL: Duration = Duration::from_secs(5);
const STRICT_FOREIGN_LINEAGE_WARNING_INTERVAL: Duration = Duration::from_secs(60);
/// Equal-generation cuts in the same journal can differ transiently while
/// concurrent decisions are learned in another order (and, mid-flight, while
/// the two equal-sized sets contain different decisions). Keep serving strict
/// work until that same-lineage-position divergence has made no progress for
/// a full proposal lifetime; otherwise a gap between sequential proposals can
/// fence one member and destroy a three-participant fast quorum.
pub(super) const STRICT_SAME_LINEAGE_DIVERGENCE_QUIET_INTERVAL: Duration = Duration::from_secs(30);
const STRICT_TERMINAL_CHECKPOINT_RECORDS: usize = 4096;
/// Hard ceiling for pairwise-v3 metadata carried on the redundant regular
/// control path. This bounds the strict envelope and nested protobuf body;
/// mandatory origin-proof material has separate certificate/signature bounds.
pub(super) const STRICT_V3_CONTROL_MAX_ENCODED_BYTES: usize = 2 * 1024;
const STRICT_REPLICATION_MESSAGE_CLASS: MessageClass = MessageClass::Regular;
/// End-to-end ACKed lanes keep release/progress control independent from the
/// operation-bearing pages it acknowledges. Route-diverse control copies use
/// distinct ordering domains so loss of the primary cannot hold the alternate.
const STRICT_CONTROL_LANE: LaneId =
    LaneId::new(NonZeroU32::new(0x5354_5243).expect("strict replication lane id is non-zero"));
const STRICT_CONTROL_ALTERNATE_LANE: LaneId =
    LaneId::new(NonZeroU32::new(0x5354_5241).expect("strict alternate lane id is non-zero"));
const STRICT_BULK_LANE: LaneId =
    LaneId::new(NonZeroU32::new(0x5354_5242).expect("strict bulk lane id is non-zero"));
const NORMAL_ACCEPT_BALLOT: u64 = 0;
const OP_ID_BOOT_EPOCH_MASK: u64 = 0x0000_FFFF_FFFF_FFFF;

/// Build transport options for every production strict-replication enqueue.
///
/// Keeping the queue lifetime policy here prevents control, consensus, and
/// bulk paths from silently acquiring different transport TTLs. This TTL
/// bounds each hop's enqueue lifetime; it is not an end-to-end packet
/// deadline. Protocol retries provide reliability beyond that bound.
fn strict_replication_transport_options(
    allow_l1_compression: bool,
    transport_ttl: Duration,
) -> OverlaySendOptions {
    let options = OverlaySendOptions::default().expire_after(transport_ttl);
    if allow_l1_compression {
        options.allow_l1_compression()
    } else {
        options
    }
}

/// Stable identity for one logical strict protocol transmission. The ordered
/// overlay owns retransmission after accepting this identity, so protocol
/// retries reuse that ownership instead of allocating another retained seq.
fn strict_retained_logical_send(topic: &str, body: &StrictBody) -> [u8; 32] {
    let encoded = repl_proto::wrap_strict(topic, body.clone()).encode_to_vec();
    let hash = digest(&SHA256, &encoded);
    let mut identity = [0; 32];
    identity.copy_from_slice(hash.as_ref());
    identity
}

/// Independent salts keep strict timer lanes from lining up
/// even when a node has only one topic.
#[derive(Clone, Copy)]
enum StrictTimerLane {
    Admission = 0x41,
    HeadEvidence = 0x48,
    TerminalRepair = 0x54,
}

/// Return a stable initial offset in `[0, interval)` for one node/topic timer.
///
/// Only the first firing is offset; callers retain their configured interval
/// after that. FNV-1a is used explicitly instead of `DefaultHasher`, whose
/// seed and implementation are not a stable scheduling contract.
fn strict_timer_start_jitter(
    node: NodeIdentifier,
    topic: &str,
    lane: StrictTimerLane,
    interval: Duration,
) -> Duration {
    const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
    const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

    let interval_nanos = interval.as_nanos();
    if interval_nanos == 0 {
        return Duration::ZERO;
    }

    let mut hash = FNV_OFFSET_BASIS;
    for byte in (node as u64)
        .to_le_bytes()
        .into_iter()
        .chain(topic.as_bytes().iter().copied())
        .chain([lane as u8])
    {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    let jitter_nanos = u128::from(hash) % interval_nanos;
    Duration::from_nanos(
        u64::try_from(jitter_nanos)
            .expect("timer jitter is less than a Duration representable in nanoseconds"),
    )
}

/// Compute p95 of a slice of edge RTTs, clamped to
/// `[cfg.min_clock_tick(), cfg.max_clock_tick()]`. Empty input
/// → `cfg.fallback_clock_tick()`. Uses nearest-rank:
/// idx = `ceil(0.95 * n) - 1`.
pub(crate) fn p95_clock_tick_interval(samples: &[Duration], cfg: &ReplicationConfig) -> Duration {
    if samples.is_empty() {
        return cfg.fallback_clock_tick();
    }
    let mut buf: Vec<Duration> = samples.to_vec();
    buf.sort_unstable();
    let n = buf.len();
    // ceil(0.95 * n) - 1, with saturating subtraction for n=1.
    let idx_one_based = ((n as f64) * 0.95).ceil() as usize;
    let idx = idx_one_based.saturating_sub(1).min(n - 1);
    buf[idx].clamp(cfg.min_clock_tick(), cfg.max_clock_tick())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum RouteRttSet {
    Empty,
    Measured(Duration),
    Unknown,
}

fn max_route_rtt(net: &dyn StrictNet, dsts: &[NodeIdentifier]) -> RouteRttSet {
    if dsts.is_empty() {
        return RouteRttSet::Empty;
    }
    let mut maximum = None;
    for dst in dsts {
        let Some(rtt) = net.route_rtt(*dst).filter(|rtt| !rtt.is_zero()) else {
            return RouteRttSet::Unknown;
        };
        maximum = Some(maximum.map_or(rtt, |current: Duration| current.max(rtt)));
    }
    RouteRttSet::Measured(maximum.expect("non-empty route set has a measured maximum"))
}

/// Retransmissions wait for two measured route round trips plus an operator
/// configured queue/scheduler margin. The maximum missing-target RTT is used:
/// a long-haul minority target must not be hidden by a cluster percentile.
fn consensus_retry_interval(
    net: &dyn StrictNet,
    dsts: &[NodeIdentifier],
    cfg: &ReplicationConfig,
) -> Duration {
    let min = cfg.strict_consensus_retry_min();
    let max = cfg.strict_consensus_retry_max().max(min);
    let interval = match max_route_rtt(net, dsts) {
        RouteRttSet::Measured(rtt) => rtt
            .saturating_mul(2)
            .saturating_add(cfg.strict_consensus_rtt_margin()),
        RouteRttSet::Empty => min,
        RouteRttSet::Unknown => max,
    };
    interval.max(cfg.delivery_tick_interval()).clamp(min, max)
}

#[derive(Clone, Copy)]
enum ConsensusRetryPhase {
    Propose = 1,
    Accept = 2,
    ProposeAck = 3,
    AcceptAck = 4,
    Resolution = 5,
    RecoveryCommit = 6,
    TerminalDecision = 7,
}

fn consensus_retry_delay(
    base: Duration,
    cfg: &ReplicationConfig,
    node: NodeIdentifier,
    topic: &str,
    op_id: OpId,
    phase: ConsensusRetryPhase,
    attempt: u32,
) -> Duration {
    let jitter_pct = cfg.strict_consensus_retry_jitter_pct();
    if base.is_zero() || jitter_pct == 0 {
        return base;
    }
    const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
    const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;
    let mut hash = FNV_OFFSET_BASIS;
    for byte in (node as u64)
        .to_le_bytes()
        .into_iter()
        .chain(topic.as_bytes().iter().copied())
        .chain(op_id.0.to_le_bytes())
        .chain(op_id.1.to_le_bytes())
        .chain([phase as u8])
        .chain(attempt.to_le_bytes())
    {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(FNV_PRIME);
    }
    let jitter_window_nanos = base.as_nanos().saturating_mul(u128::from(jitter_pct)) / 100;
    if jitter_window_nanos == 0 {
        return base;
    }
    let jitter_nanos = u128::from(hash) % jitter_window_nanos.saturating_add(1);
    base.saturating_add(Duration::from_nanos(
        u64::try_from(jitter_nanos).unwrap_or(u64::MAX),
    ))
}

fn strict_transport_ttl(
    route_rtt: Option<Duration>,
    min: Duration,
    max: Duration,
    rtt_margin: Duration,
) -> Duration {
    let max = max.max(min);
    route_rtt
        .map(|rtt| rtt.saturating_add(rtt_margin))
        .unwrap_or(max)
        .clamp(min, max)
}

// ---------- OpId ----------

/// Globally unique op identifier. Encoded on the wire as `(hi, lo)`.
pub(crate) type OpId = (u64, u64);

#[inline]
pub(crate) fn make_op_id(self_id: NodeIdentifier, boot_epoch: u64, counter: u64) -> OpId {
    let hi = ((self_id as u64) << 48) | (boot_epoch & 0x0000_FFFF_FFFF_FFFF);
    (hi, counter)
}

/// Tempo fast quorum = ceil(3n/4). Defined in its own fn so unit tests can
/// pin the values across cluster sizes.
#[inline]
pub(crate) fn fast_quorum_size(n: usize) -> usize {
    if n == 0 { 0 } else { (3 * n).div_ceil(4) }
}

