/// A responder-side immutable image for one v2 snapshot transfer. This is
/// deliberately ephemeral: after a restart the requester detects the missing
/// transfer and restarts from a fresh, self-consistent image.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(super) enum SnapshotFormat {
    Repository,
    S2sEnvelope,
}

#[derive(Clone)]
pub(super) struct SnapshotTransfer {
    pub(super) id: u64,
    pub(super) format: SnapshotFormat,
    pub(super) version: u64,
    pub(super) snapshot_msgpack: Bytes,
    pub(super) snapshot_sha256: Bytes,
    pub(super) rank: HistoryRank,
    pub(super) terminal_decision_generation: u64,
    /// Present only for a V7 bound snapshot envelope.
    pub(super) terminal_cut: Option<TerminalCut>,
    pub(super) last_used_at: Instant,
}

/// Receiver-side assembly state. Chunks are accepted strictly in byte order;
/// the repository never sees this image until its length and SHA-256 match.
pub(super) struct SnapshotReceiveTransfer {
    pub(super) id: u64,
    pub(super) format: SnapshotFormat,
    pub(super) version: u64,
    pub(super) total_bytes: u64,
    pub(super) snapshot_sha256: Bytes,
    pub(super) rank: HistoryRank,
    pub(super) terminal_decision_generation: u64,
    pub(super) next_cursor: u64,
    pub(super) snapshot_msgpack: Vec<u8>,
    pub(super) last_used_at: Instant,
}

#[async_trait]
pub(crate) trait StrictNet: Send + Sync + 'static {
    async fn send_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError>;
    /// Send authenticated control traffic with one route-diverse duplicate.
    /// The default keeps lightweight test networks on their ordinary
    /// single-send behavior; production overlays override it when a lost
    /// one-way control message would strand a protocol round.
    async fn send_redundant_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError> {
        self.send_unicast(dst, topic, body).await
    }
    /// Send bounded strict-repair control traffic while attributing the
    /// physical enqueue to a stable reason and phase. Production overrides
    /// this method so route-diverse copies are counted separately.
    async fn send_redundant_catchup_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        reason: CatchupReason,
        phase: CatchupPhase,
    ) -> Result<(), ReplicationError> {
        let encoded_len = self.encoded_strict_payload_len(topic, &body).unwrap_or(0);
        let result = self.send_redundant_unicast(dst, topic, body).await;
        metrics::record_strict_catchup_send_attempt(
            reason,
            phase,
            StrictCatchupLane::Control,
            if result.is_ok() {
                StrictCatchupSendOutcome::Enqueued
            } else {
                StrictCatchupSendOutcome::Rejected
            },
            encoded_len,
        );
        result
    }
    async fn send_bulk_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        _retry_delay: Duration,
    ) -> Result<(), ReplicationError> {
        self.send_unicast(dst, topic, body).await
    }
    async fn send_bulk_catchup_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        retry_delay: Duration,
        reason: CatchupReason,
        phase: CatchupPhase,
    ) -> Result<(), ReplicationError> {
        let encoded_len = self.encoded_strict_payload_len(topic, &body).unwrap_or(0);
        let result = self.send_bulk_unicast(dst, topic, body, retry_delay).await;
        metrics::record_strict_catchup_send_attempt(
            reason,
            phase,
            StrictCatchupLane::Bulk,
            if result.is_ok() {
                StrictCatchupSendOutcome::Enqueued
            } else {
                StrictCatchupSendOutcome::Rejected
            },
            encoded_len,
        );
        result
    }
    /// Release a retained bulk-page reservation after the corresponding
    /// continuation or final acknowledgement has passed protocol validation.
    fn acknowledge_bulk_unicast(
        &self,
        _dst: NodeIdentifier,
        _topic: &str,
        _page: BulkPageIdentity,
    ) {
    }
    /// Cancel any retained page for a departed or replaced incarnation.
    fn cancel_bulk_unicast(&self, dst: NodeIdentifier, topic: &str) {
        let _ = (dst, topic);
    }
    async fn send_multicast(
        &self,
        dsts: &[NodeIdentifier],
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError>;
    async fn send_broadcast(&self, topic: &str, body: StrictBody) -> Result<(), ReplicationError>;
    /// Encoded strict replication payload length. Production implementations
    /// include any origin-proof bytes added immediately before transmission.
    fn encoded_strict_payload_len(
        &self,
        topic: &str,
        body: &StrictBody,
    ) -> Result<usize, ReplicationError> {
        Ok(repl_proto::wrap_strict(topic, body.clone()).encoded_len())
    }
    /// Encoded strict replication payload length under the v2 contract.
    ///
    /// Unlike `encoded_strict_payload_len`, this deliberately reserves the
    /// end-to-end origin-authentication envelope even before the local LSA
    /// advertises mandatory protocol v8. It protects terminal admission and startup validation
    /// from accepting records that cannot later fit in authenticated catchup.
    fn encoded_v2_strict_payload_len(
        &self,
        topic: &str,
        body: &StrictBody,
    ) -> Result<usize, ReplicationError> {
        Ok(repl_proto::wrap_strict(topic, body.clone()).encoded_len())
    }
    fn alive_members(&self) -> Vec<NodeIdentifier>;
    /// Total number of strict replication participants known to this node,
    /// including members that are currently unreachable. A terminal journal
    /// rotation retires the local op range permanently, so it is only safe
    /// when a fast quorum of this known membership is present and
    /// acknowledges the identical head. A partitioned minority must never
    /// rotate: the retirement floor would cover ops the majority still holds
    /// live and per-op reconciliation would be impossible forever.
    fn strict_participant_count(&self) -> usize;
    /// One current incarnation for every known strict participant, including
    /// the local node. Recovery freezes this view and then excludes itself.
    fn strict_participant_incarnations(&self) -> Vec<(NodeIdentifier, u64)> {
        self.alive_members()
            .into_iter()
            .filter_map(|node| self.member_boot_epoch(node).map(|epoch| (node, epoch)))
            .collect()
    }
    fn member_boot_epoch(&self, _node: NodeIdentifier) -> Option<u64> {
        None
    }
    fn has_route(&self, _dst: NodeIdentifier, _level: ServiceLevel) -> bool {
        true
    }
    fn has_live_route(&self, dst: NodeIdentifier, level: ServiceLevel) -> bool {
        self.has_route(dst, level)
    }
    /// Effective strict protocol floor for this replication view. The
    /// participant floor covers strict endpoints; the transit floor covers
    /// relay-capable members so an old relay cannot strip opaque frames.
    fn strict_replication_protocol_version(&self) -> u32 {
        0
    }

    /// Local capability may fall below the advertised/LSDB floor before an
    /// asynchronous LSA downgrade reaches peers. Inbound v2 participation
    /// must consult this immediate fail-closed value.
    fn local_strict_replication_protocol_version(&self) -> u32 {
        self.strict_replication_protocol_version()
    }
    /// Version advertised by one peer. Terminal-state catchup adds a
    /// continuation exchange which legacy binaries do not understand, so it
    /// must be gated by the requester rather than only by the cluster floor.
    fn peer_strict_replication_protocol_version(&self, _peer: NodeIdentifier) -> u32 {
        self.strict_replication_protocol_version()
    }
    /// Freeze the participant/transit capability floor and strict target set
    /// from one membership view. Production avoids sampling these
    /// independently while LSDB updates are in flight; the default keeps
    /// test transports simple.
    fn strict_protocol_snapshot(&self) -> StrictProtocolSnapshot {
        StrictProtocolSnapshot {
            negotiated_version: self.strict_replication_protocol_version(),
            targets: self
                .alive_members()
                .into_iter()
                .filter(|node| {
                    replication_protocol::strict_participant_version_supported(
                        self.peer_strict_replication_protocol_version(*node),
                    )
                })
                .map(|node| StrictProtocolTarget {
                    node,
                    boot_epoch: self.member_boot_epoch(node).unwrap_or_default(),
                })
                .collect(),
        }
    }
    fn unsupported_active_protocol_peers(&self, _required_version: u32) -> usize {
        0
    }
    /// Whether every currently known strict participant, including an
    /// unreachable participant retained in membership, supports the
    /// protocol-v8 recovery contract. Recovery has no legacy fallback.
    fn strict_recovery_v8_ready(&self) -> bool {
        self.local_strict_replication_protocol_version() >= STRICT_PROTOCOL_VERSION_V8
            && self.strict_replication_protocol_version() >= STRICT_PROTOCOL_VERSION_V8
            && self.unsupported_active_protocol_peers(STRICT_PROTOCOL_VERSION_V8) == 0
    }
    fn strict_protocol_state_dir(&self) -> Option<PathBuf> {
        None
    }
    /// Whether this node can originate bounded, authenticated v2 wire frames.
    /// This is intentionally independent of the local LSA version so v8
    /// capability activation can fail closed before advertisement.
    fn current_protocol_prerequisites_ready(
        &self,
        topic: &str,
        strict_max_catchup_bytes: usize,
    ) -> bool {
        // Test and alternate transports inherit this conservative check. The
        // production implementation below additionally reserves the actual
        // origin-authentication envelope for its local identity.
        v2_control_prerequisite_bodies(u32::MAX as NodeIdentifier)
            .into_iter()
            .all(|body| {
                self.encoded_v2_strict_payload_len(topic, &body)
                    .is_ok_and(|encoded_len| {
                        v2_prerequisite_payload_fits(
                            self.max_replication_payload_bytes(),
                            strict_max_catchup_bytes,
                            encoded_len,
                        )
                    })
            })
    }
    /// Maximum payload budget for one replication message after accounting for
    /// the local transport frame and overlay envelope.
    fn max_replication_payload_bytes(&self) -> usize {
        usize::MAX
    }
    /// Clamp the local advertisement when one registered strict repository
    /// cannot honor the current protocol contract. A later coordinated
    /// registration pass may clear this non-sticky capability loss.
    fn report_strict_replication_repository_capability_loss(&self) {}
    /// Snapshot of every directed-edge RTT in the overlay's LSDB. Used to
    /// scale the clock-tick cadence to measured network latency.
    fn edge_rtt_snapshot(&self) -> Vec<Duration>;
    /// Measured end-to-end RTT for the currently selected reliable route.
    /// `None` preserves conservative timing when no route measurement exists.
    fn route_rtt(&self, _dst: NodeIdentifier) -> Option<Duration> {
        None
    }
}

/// Production `StrictNet` impl that wraps `OverlayNetwork`.
pub(crate) struct OverlayStrictNet {
    overlay: OverlayNetwork,
    participant_capability: Arc<StrictParticipantCapability>,
    bulk_pacer: Arc<BulkPacer>,
    bulk_reservation_ttl: Duration,
    consensus_rtt_margin: Duration,
    transport_ttl_min: Duration,
    transport_ttl_max: Duration,
    /// Strict participants observed with a live (non-tombstone) LSA in this
    /// process, including members that later became unreachable. The terminal
    /// journal rotation quorum must be evaluated against this monotonic set
    /// rather than the current LSDB view: a partition ages peer LSAs out of
    /// the local view, so a minority could otherwise rotate alone and
    /// permanently retire ops the majority still holds live.
    known_participants: Mutex<HashSet<NodeIdentifier>>,
    /// Last observed incarnation and protocol version for every node that has
    /// advertised itself as a strict participant. Unlike the supported quorum
    /// set above, this retains pre-v8 participants after route/LSA loss so an
    /// aged-out legacy node remains a fail-closed recovery blocker until a
    /// definitive Left tombstone or a v8 advertisement for its incarnation.
    known_participant_versions: Mutex<HashMap<NodeIdentifier, (u64, u32)>>,
}

struct StrictOriginProofMetadata<'a> {
    certificate_chain: &'a [Vec<u8>],
    maximum_signature_len: usize,
}

trait StrictOriginProofProvider {
    fn origin_signature_metadata(&self) -> Result<StrictOriginProofMetadata<'_>, ReplicationError>;

    fn sign_origin_payload(&self, payload: &[u8]) -> Result<OriginSignature, ReplicationError>;
}

impl StrictOriginProofProvider for OverlayNetwork {
    fn origin_signature_metadata(&self) -> Result<StrictOriginProofMetadata<'_>, ReplicationError> {
        let metadata = OverlayNetwork::origin_signature_metadata(self)
            .map_err(|error| ReplicationError::OriginAuthentication(error.to_string()))?;
        Ok(StrictOriginProofMetadata {
            certificate_chain: metadata.certificate_chain(),
            maximum_signature_len: metadata.maximum_signature_len(),
        })
    }

    fn sign_origin_payload(&self, payload: &[u8]) -> Result<OriginSignature, ReplicationError> {
        OverlayNetwork::sign_origin_payload(self, payload)
            .map_err(|error| ReplicationError::OriginAuthentication(error.to_string()))
    }
}

fn strict_origin_auth_with_provider(
    provider: &(impl StrictOriginProofProvider + ?Sized),
    topic: &str,
    body: &StrictBody,
    origin_node: u32,
    origin_boot_epoch: u64,
) -> Result<StrictOriginAuth, ReplicationError> {
    let signing_payload =
        repl_proto::strict_origin_signing_payload(topic, body, origin_node, origin_boot_epoch)?;
    let proof = provider.sign_origin_payload(&signing_payload)?;
    let origin_auth = StrictOriginAuth {
        origin_node,
        origin_boot_epoch,
        signature_scheme: u32::from(proof.signature_scheme()),
        certificate_chain: proof
            .certificate_chain()
            .iter()
            .map(|certificate| Bytes::copy_from_slice(certificate))
            .collect(),
        signature: Bytes::copy_from_slice(proof.signature()),
    };
    if !repl_proto::strict_origin_auth_within_bounds(&origin_auth) {
        return Err(ReplicationError::OriginAuthentication(
            "local certificate proof exceeds the strict v2 wire bound".to_owned(),
        ));
    }
    Ok(origin_auth)
}

fn encode_strict_payload_with_provider(
    provider: &(impl StrictOriginProofProvider + ?Sized),
    topic: &str,
    body: StrictBody,
    origin_node: u32,
    origin_boot_epoch: u64,
    on_origin_auth_failure: impl FnOnce(),
) -> Result<Bytes, ReplicationError> {
    let origin_auth = match strict_origin_auth_with_provider(
        provider,
        topic,
        &body,
        origin_node,
        origin_boot_epoch,
    ) {
        Ok(origin_auth) => origin_auth,
        Err(error) => {
            on_origin_auth_failure();
            return Err(error);
        }
    };
    let message = repl_proto::wrap_strict_with_origin_auth(topic, body, origin_auth);
    Ok(repl_proto::encode(&message)?)
}

fn encoded_v2_strict_payload_len_with_provider(
    provider: &(impl StrictOriginProofProvider + ?Sized),
    topic: &str,
    body: &StrictBody,
) -> Result<usize, ReplicationError> {
    let metadata = provider.origin_signature_metadata()?;
    if !repl_proto::strict_origin_auth_shape_within_bounds(
        metadata
            .certificate_chain
            .iter()
            .map(|certificate| certificate.len()),
        metadata.maximum_signature_len,
    ) {
        return Err(ReplicationError::OriginAuthentication(
            "local certificate proof exceeds the strict v2 wire bound".to_owned(),
        ));
    }

    Ok(repl_proto::strict_encoded_len_with_origin_auth_budget(
        topic, body,
    ))
}

impl OverlayStrictNet {
    pub(crate) fn new(
        overlay: OverlayNetwork,
        participant_capability: Arc<StrictParticipantCapability>,
        cfg: &ReplicationConfig,
        shutdown: CancellationToken,
    ) -> Self {
        Self {
            overlay,
            participant_capability,
            bulk_pacer: BulkPacer::new_with_shutdown(
                cfg.strict_bulk_max_in_flight_bytes_per_next_hop(),
                cfg.strict_bulk_rate_bytes_per_second_per_next_hop(),
                shutdown,
            ),
            bulk_reservation_ttl: cfg.pending_propose_ttl(),
            consensus_rtt_margin: cfg.strict_consensus_rtt_margin(),
            transport_ttl_min: cfg.strict_transport_ttl_min(),
            transport_ttl_max: cfg.strict_transport_ttl_max(),
            known_participants: Mutex::new(HashSet::new()),
            known_participant_versions: Mutex::new(HashMap::new()),
        }
    }

    fn reconcile_known_participants(&self) {
        let mut known = self.known_participants.lock();
        let mut versions = self.known_participant_versions.lock();
        for member in self.overlay.members() {
            let capabilities = Self::member_replication_capabilities(&member);
            reconcile_known_participant(
                &mut known,
                &mut versions,
                member.node_id(),
                member.boot_epoch(),
                member.status(),
                capabilities.strict_enabled(),
                capabilities.strict_participant_protocol_version(),
            );
        }
        let local = self.local_replication_capabilities();
        if local.strict_enabled() {
            let node = self.overlay.local_node_id();
            known.insert(node);
            let boot_epoch = self
                .overlay
                .member(node)
                .map(|member| member.boot_epoch())
                .unwrap_or_default();
            versions.insert(
                node,
                (boot_epoch, local.strict_participant_protocol_version()),
            );
        }
    }

    fn transport_ttl(&self, dsts: &[NodeIdentifier]) -> Duration {
        let mut route_rtt = None;
        for dst in dsts
            .iter()
            .copied()
            .filter(|dst| *dst != self.overlay.local_node_id())
        {
            let Some(rtt) = self.overlay.route_latency_with_metric(
                dst,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
            ) else {
                return self.transport_ttl_max.max(self.transport_ttl_min);
            };
            route_rtt = Some(route_rtt.map_or(rtt, |current: Duration| current.max(rtt)));
        }
        strict_transport_ttl(
            route_rtt,
            self.transport_ttl_min,
            self.transport_ttl_max,
            self.consensus_rtt_margin,
        )
    }

    fn member_replication_capabilities(
        member: &crate::overlay::MemberSnapshot,
    ) -> ReplicationProtocolCapabilities {
        let legacy = member.replication_services();
        replication_protocol::advertised_replication_capabilities(
            member.upper_layer_capabilities(),
            legacy.strict(),
            legacy.content(),
            legacy.owner(),
            member.strict_replication_protocol_version(),
        )
    }

    fn local_replication_capabilities(&self) -> ReplicationProtocolCapabilities {
        let services = self.overlay.legacy_local_replication_services();
        ReplicationProtocolCapabilities::new(
            services.strict(),
            services.content(),
            services.owner(),
            self.participant_capability.protocol_version(),
        )
    }

    fn protocol_members(&self) -> Vec<ProtocolMember> {
        self.overlay
            .members()
            .into_iter()
            .map(|member| {
                let capabilities = Self::member_replication_capabilities(&member);
                ProtocolMember::new(
                    member.node_id(),
                    member.boot_epoch(),
                    member.status().is_reachable(),
                    capabilities.strict_enabled(),
                    capabilities.strict_participant_protocol_version(),
                )
            })
            .collect()
    }

    fn protocol_snapshot(&self) -> StrictProtocolSnapshot {
        let local = self.local_replication_capabilities();
        replication_protocol::strict_protocol_snapshot(
            self.protocol_members(),
            local
                .strict_enabled()
                .then(|| local.strict_participant_protocol_version()),
        )
    }

    fn encode_strict_payload(
        &self,
        topic: &str,
        body: StrictBody,
    ) -> Result<Bytes, ReplicationError> {
        // Always attach an end-to-end proof in production. The field is
        // additive, so legacy decoders ignore it, but this avoids an LSA
        // transition racing a v2-associated response into an unsigned frame.
        encode_strict_payload_with_provider(
            &self.overlay,
            topic,
            body,
            self.overlay.local_node_id() as u32,
            self.overlay.local_boot_epoch(),
            || self.participant_capability.disable_permanently(),
        )
    }

    async fn send_redundant_unicast_inner(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        catchup_metric: Option<(CatchupReason, CatchupPhase)>,
    ) -> Result<(), ReplicationError> {
        let retained_logical_send = strict_retained_logical_send(topic, &body);
        let recovery_v8 = is_recovery_v8_body(&body);
        let v3_metadata_len = is_v3_metadata_control(&body)
            .then(|| repl_proto::wrap_strict(topic, body.clone()).encoded_len());
        let bytes = self.encode_strict_payload(topic, body)?;
        let encoded_len = bytes.len();
        if v3_metadata_len.is_some_and(|len| len > STRICT_V3_CONTROL_MAX_ENCODED_BYTES) {
            if let Some((reason, phase)) = catchup_metric {
                metrics::record_strict_catchup_send_attempt(
                    reason,
                    phase,
                    StrictCatchupLane::Control,
                    StrictCatchupSendOutcome::Rejected,
                    encoded_len,
                );
            }
            return Err(ReplicationError::Malformed(
                "strict v3 control frame exceeds 2 KiB encoded limit",
            ));
        }
        let primary_next_hop = self.overlay.route_to_with_metric(
            dst,
            ServiceLevel::Reliable,
            RoutingMetric::ReliableCost,
        );
        let primary = self
            .overlay
            .send_unicast_on_lane_with_routing_metric_and_options(
                dst,
                STRICT_CONTROL_LANE,
                REPLICATION_SERVICE_TAG,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
                STRICT_REPLICATION_MESSAGE_CLASS,
                bytes.clone(),
                strict_replication_transport_options(false, self.transport_ttl(&[dst]))
                    .retain_logical_send(retained_logical_send),
            )
            .await;
        if recovery_v8 {
            metrics::record_strict_recovery_send_attempt(encoded_len);
        }
        if let Some((reason, phase)) = catchup_metric {
            metrics::record_strict_catchup_send_attempt(
                reason,
                phase,
                StrictCatchupLane::Control,
                if primary.is_ok() {
                    StrictCatchupSendOutcome::Enqueued
                } else {
                    StrictCatchupSendOutcome::Rejected
                },
                encoded_len,
            );
        }
        let Some(primary_next_hop) = primary_next_hop else {
            return primary.map_err(Into::into);
        };

        // A duplicate is useful only when it takes a different first hop.
        // Account for it independently so the physical-byte series exposes
        // route redundancy rather than reporting one logical send.
        let alternate = self
            .overlay
            .send_unicast_on_lane_with_routing_metric_and_options(
                dst,
                STRICT_CONTROL_ALTERNATE_LANE,
                REPLICATION_SERVICE_TAG,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
                STRICT_REPLICATION_MESSAGE_CLASS,
                bytes,
                strict_replication_transport_options(false, self.transport_ttl(&[dst]))
                    .retain_logical_send(retained_logical_send)
                    .avoid_first_hop(primary_next_hop),
            )
            .await;
        if recovery_v8 {
            metrics::record_strict_recovery_send_attempt(encoded_len);
        }
        if let Some((reason, phase)) = catchup_metric {
            metrics::record_strict_catchup_send_attempt(
                reason,
                phase,
                StrictCatchupLane::Control,
                if alternate.is_ok() {
                    StrictCatchupSendOutcome::Enqueued
                } else {
                    StrictCatchupSendOutcome::Rejected
                },
                encoded_len,
            );
        }
        match primary {
            Ok(()) => Ok(()),
            Err(primary_error) => alternate.map_err(|_| primary_error).map_err(Into::into),
        }
    }

    async fn send_bulk_unicast_inner(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        _retry_delay: Duration,
        catchup_metric: Option<(CatchupReason, CatchupPhase)>,
    ) -> Result<(), ReplicationError> {
        let retained_logical_send = strict_retained_logical_send(topic, &body);
        let recovery_v8 = is_recovery_v8_body(&body);
        let page_identity = bulk_page_identity(&body);
        let encode_started_at = Instant::now();
        let encoded = self.encode_strict_payload(topic, body);
        metrics::record_pipeline_stage(
            ReplicationPipelineKind::Strict,
            ReplicationPipelineStage::ProtobufEncode,
            encode_started_at.elapsed(),
        );
        let bytes = encoded?;
        let encoded_len = bytes.len();
        let next_hop = self.overlay.route_to_with_metric(
            dst,
            ServiceLevel::Reliable,
            RoutingMetric::ReliableCost,
        );
        if next_hop.is_none() {
            return Err(ReplicationError::Overlay(
                crate::overlay::OverlayError::Send(
                    shitspeak_s2s_transport::SendError::NoSuitableTransport { node: dst },
                ),
            ));
        }
        // Only v3 pages have a correlated requester/reducer that can safely
        // re-drive a nonblocking Busy result. Legacy v1/v2 responses rely on
        // the ordered Reliable lane itself once accepted and must not be
        // abandoned by a pacer rejection with no cached-page owner.
        let reservation = if page_identity != BulkPageIdentity::Legacy
            && let Some(next_hop) = next_hop
        {
            match self
                .bulk_pacer
                .try_reserve(dst, topic, page_identity, next_hop, encoded_len)
            {
                Ok(reservation) if reservation.is_coalesced() => return Ok(()),
                Ok(reservation) => Some(reservation),
                Err(BulkAdmissionError::Busy { retry_after }) => {
                    record_bulk_catchup_backpressure(catchup_metric, retry_after);
                    if let Some((reason, phase)) = catchup_metric {
                        metrics::record_strict_catchup_send_attempt(
                            reason,
                            phase,
                            StrictCatchupLane::Bulk,
                            StrictCatchupSendOutcome::Backpressured,
                            encoded_len,
                        );
                    }
                    return Err(ReplicationError::StrictBulkAdmissionBusy { retry_after });
                }
                Err(BulkAdmissionError::FrameTooLarge {
                    encoded_bytes,
                    max_bytes,
                }) => {
                    return Err(ReplicationError::StrictBulkFrameTooLarge {
                        encoded_bytes,
                        max_bytes,
                    });
                }
            }
        } else {
            None
        };
        let result = self
            .overlay
            .send_unicast_on_lane_with_routing_metric_and_options(
                dst,
                STRICT_BULK_LANE,
                REPLICATION_SERVICE_TAG,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
                STRICT_REPLICATION_MESSAGE_CLASS,
                bytes.clone(),
                strict_replication_transport_options(true, self.transport_ttl(&[dst]))
                    .retain_logical_send(retained_logical_send),
            )
            .await;
        if recovery_v8 {
            metrics::record_strict_recovery_send_attempt(encoded_len);
        }

        if result.as_ref().is_err_and(replication_bulk_backpressure) {
            record_bulk_catchup_backpressure(catchup_metric, Duration::ZERO);
        }
        if let Some((reason, phase)) = catchup_metric {
            let outcome = if result.is_ok() {
                StrictCatchupSendOutcome::Enqueued
            } else if result.as_ref().is_err_and(replication_bulk_backpressure) {
                StrictCatchupSendOutcome::Backpressured
            } else {
                StrictCatchupSendOutcome::Rejected
            };
            metrics::record_strict_catchup_send_attempt(
                reason,
                phase,
                StrictCatchupLane::Bulk,
                outcome,
                encoded_len,
            );
        }
        match result {
            Ok(()) => {
                if let Some(reservation) = reservation {
                    reservation.retain_until(self.bulk_reservation_ttl);
                }
                Ok(())
            }
            Err(error) => Err(error.into()),
        }
    }
}

fn record_bulk_catchup_backpressure(
    catchup_metric: Option<(CatchupReason, CatchupPhase)>,
    backoff: Duration,
) {
    if let Some((reason, phase)) = catchup_metric {
        metrics::record_strict_catchup_backpressure(
            reason,
            phase,
            StrictCatchupBackpressureEvent::Backpressured,
            backoff,
        );
    }
}

fn bulk_page_identity(body: &StrictBody) -> BulkPageIdentity {
    match body {
        StrictBody::TerminalSyncPage(page) => {
            BulkPageIdentity::terminal(page.transfer_id, page.request_nonce)
        }
        StrictBody::CatchupResp(response) => {
            let Some(transfer) = response.history_transfer.as_ref() else {
                return BulkPageIdentity::Legacy;
            };
            BulkPageIdentity::history(transfer.transfer_id, transfer.request_nonce)
        }
        StrictBody::RecoveryTerminalPage(page) => {
            BulkPageIdentity::recovery_terminal(page.transfer_id, page.request_nonce)
        }
        StrictBody::RecoverySnapshotPage(page) => {
            BulkPageIdentity::recovery_snapshot(page.transfer_id, page.request_nonce)
        }
        _ => BulkPageIdentity::Legacy,
    }
}

fn minimum_v2_catchup_response_body(history_node: NodeIdentifier) -> StrictBody {
    // This is the smallest semantically valid v2 response: an empty history
    // probe after the responder has completed terminal-fence pagination.
    // It is an activation-time floor, not a substitute for normal per-frame
    // admission checks on actual terminal states or snapshot chunks.
    StrictBody::CatchupResp(StrictCatchupResp {
        snapshot_version: 0,
        snapshot_msgpack: Bytes::new(),
        ops: Vec::new(),
        has_more: false,
        next_chunk_token: 0,
        too_old_use_snapshot: false,
        history_version: 0,
        history_freshness: 0,
        runtime_started_at: 1,
        history_node: history_node as u32,
        terminal_states: Vec::new(),
        next_terminal_state_cursor: u64::MAX,
        terminal_states_has_more: false,
        terminal_sync_only: false,
        request_force_snapshot: false,
        request_history_probe_only: true,
        terminal_decision_generation: 0,
        snapshot_transfer_id: 0,
        snapshot_chunk_cursor: 0,
        snapshot_next_cursor: 0,
        snapshot_total_bytes: 0,
        snapshot_sha256: Bytes::new(),
        snapshot_has_more: false,
        snapshot_transfer_rejected: false,
        history_transfer: None,
    })
}

/// The smallest snapshot-control response that must always be transmitable
/// under v2. It deliberately includes every optional field that the chunk
/// and rejection control paths can require, with maximal scalar widths. The
/// value is an activation-time sizing sentinel only; no peer receives this
/// semantically contradictory combination of flags.
fn minimum_v2_snapshot_control_response_body(history_node: NodeIdentifier) -> StrictBody {
    StrictBody::CatchupResp(StrictCatchupResp {
        snapshot_version: u64::MAX,
        snapshot_msgpack: Bytes::from_static(&[0]),
        ops: Vec::new(),
        has_more: true,
        next_chunk_token: u64::MAX,
        too_old_use_snapshot: true,
        history_version: u64::MAX,
        history_freshness: i64::MAX,
        runtime_started_at: u64::MAX,
        history_node: history_node as u32,
        terminal_states: Vec::new(),
        next_terminal_state_cursor: u64::MAX,
        terminal_states_has_more: true,
        terminal_sync_only: true,
        request_force_snapshot: true,
        request_history_probe_only: true,
        terminal_decision_generation: u64::MAX,
        snapshot_transfer_id: u64::MAX,
        snapshot_chunk_cursor: u64::MAX,
        snapshot_next_cursor: u64::MAX,
        snapshot_total_bytes: u64::MAX,
        snapshot_sha256: Bytes::from_static(&[0; 32]),
        snapshot_has_more: true,
        snapshot_transfer_rejected: true,
        history_transfer: None,
    })
}

fn v2_control_prerequisite_bodies(history_node: NodeIdentifier) -> [StrictBody; 2] {
    [
        minimum_v2_catchup_response_body(history_node),
        minimum_v2_snapshot_control_response_body(history_node),
    ]
}

fn v2_prerequisite_payload_fits(
    local_budget: usize,
    strict_max_catchup_bytes: usize,
    encoded_len: usize,
) -> bool {
    local_budget >= repl_proto::STRICT_V2_MAX_REPLICATION_PAYLOAD_BYTES
        && encoded_len
            <= strict_max_catchup_bytes
                .min(local_budget)
                .min(repl_proto::STRICT_V2_MAX_REPLICATION_PAYLOAD_BYTES)
}

/// Whether a v3 frame is bounded control metadata. Terminal pages remain
/// control only while they contain no decisions; operation-bearing delta and
/// checkpoint pages must use the bulk lane.
pub(super) fn is_v3_history_final_ack_confirmation(response: &StrictCatchupResp) -> bool {
    let Some(correlation) = response.history_transfer.clone() else {
        return false;
    };
    *response
        == StrictCatchupResp {
            history_transfer: Some(correlation),
            ..Default::default()
        }
}

pub(super) fn is_v3_metadata_control(body: &StrictBody) -> bool {
    match body {
        StrictBody::ClockProbeReq(_)
        | StrictBody::ClockProbeResp(_)
        | StrictBody::HistoryProbeReq(_)
        | StrictBody::HistoryProbeResp(_)
        | StrictBody::TerminalSyncReq(_)
        | StrictBody::TerminalSyncAck(_)
        | StrictBody::RecoveryProbeReq(_)
        | StrictBody::RecoveryProbeResp(_)
        | StrictBody::RecoveryTerminalReq(_)
        | StrictBody::RecoveryTerminalAck(_)
        | StrictBody::RecoverySnapshotReq(_)
        | StrictBody::RecoverySnapshotAck(_) => true,
        StrictBody::TerminalSyncPage(page) => {
            page.checkpoint_states.is_empty() && page.deltas.is_empty()
        }
        StrictBody::RecoveryTerminalPage(page) => page.checkpoint_states.is_empty(),
        StrictBody::RecoverySnapshotPage(page) => page.snapshot_bytes.is_empty(),
        StrictBody::CatchupReq(request) => request
            .history_transfer
            .as_ref()
            .is_some_and(|transfer| transfer.final_ack),
        StrictBody::CatchupResp(response) => is_v3_history_final_ack_confirmation(response),
        _ => false,
    }
}

fn is_recovery_v8_body(body: &StrictBody) -> bool {
    matches!(
        body,
        StrictBody::RecoveryProbeReq(_)
            | StrictBody::RecoveryProbeResp(_)
            | StrictBody::RecoveryTerminalReq(_)
            | StrictBody::RecoveryTerminalPage(_)
            | StrictBody::RecoveryTerminalAck(_)
            | StrictBody::RecoverySnapshotReq(_)
            | StrictBody::RecoverySnapshotPage(_)
            | StrictBody::RecoverySnapshotAck(_)
    )
}

pub(super) fn validate_v3_metadata_control(
    net: &dyn StrictNet,
    topic: &str,
    body: &StrictBody,
) -> Result<usize, ReplicationError> {
    if !is_v3_metadata_control(body) {
        return Err(ReplicationError::Malformed(
            "operation-bearing frame is not v3 control metadata",
        ));
    }
    // Bound the protocol metadata itself. The mandatory origin proof is a
    // common authenticated-transport envelope whose independently bounded
    // certificate/signature material can exceed 2 KiB even for an empty
    // body; including it here would reject every production v3 probe. The
    // full physical size is still returned for exact byte accounting.
    let metadata_len = repl_proto::wrap_strict(topic, body.clone()).encoded_len();
    if metadata_len > STRICT_V3_CONTROL_MAX_ENCODED_BYTES {
        return Err(ReplicationError::Malformed(
            "strict v3 control frame exceeds 2 KiB encoded limit",
        ));
    }
    net.encoded_strict_payload_len(topic, body)
}

/// Reconcile one overlay member against the known strict participant set.
///
/// A graceful-leave tombstone is the only definitive removal signal the
/// LSDB exposes. Members that merely become unreachable (Failed, or an
/// LSA that has not refreshed) stay in the known set so a partitioned
/// minority can never rotate the terminal journal alone.
fn reconcile_known_participant(
    known: &mut HashSet<NodeIdentifier>,
    versions: &mut HashMap<NodeIdentifier, (u64, u32)>,
    node_id: NodeIdentifier,
    boot_epoch: u64,
    status: MemberStatus,
    strict_enabled: bool,
    protocol_version: u32,
) {
    if status == MemberStatus::Left {
        known.remove(&node_id);
        versions.remove(&node_id);
        return;
    }
    if strict_enabled {
        let observed = versions
            .entry(node_id)
            .or_insert((boot_epoch, protocol_version));
        if boot_epoch >= observed.0 {
            *observed = (boot_epoch, protocol_version);
        }
    } else if let Some(observed) = versions.get_mut(&node_id)
        && boot_epoch >= observed.0
    {
        *observed = (boot_epoch, 0);
    }
    if strict_enabled
        && replication_protocol::strict_participant_version_supported(protocol_version)
    {
        known.insert(node_id);
    }
}

#[async_trait]
impl StrictNet for OverlayStrictNet {
    async fn send_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError> {
        let retained_logical_send = strict_retained_logical_send(topic, &body);
        let allow_l1_compression = matches!(&body, StrictBody::CatchupResp(_));
        let encode_started_at = Instant::now();
        let encoded = self.encode_strict_payload(topic, body);
        metrics::record_pipeline_stage(
            ReplicationPipelineKind::Strict,
            ReplicationPipelineStage::ProtobufEncode,
            encode_started_at.elapsed(),
        );
        let bytes = encoded?;
        self.overlay
            .send_unicast_on_lane_with_routing_metric_and_options(
                dst,
                STRICT_CONTROL_LANE,
                REPLICATION_SERVICE_TAG,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
                STRICT_REPLICATION_MESSAGE_CLASS,
                bytes,
                strict_replication_transport_options(
                    allow_l1_compression,
                    self.transport_ttl(&[dst]),
                )
                .retain_logical_send(retained_logical_send),
            )
            .await?;
        Ok(())
    }

    async fn send_redundant_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError> {
        self.send_redundant_unicast_inner(dst, topic, body, None)
            .await
    }

    async fn send_redundant_catchup_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        reason: CatchupReason,
        phase: CatchupPhase,
    ) -> Result<(), ReplicationError> {
        self.send_redundant_unicast_inner(dst, topic, body, Some((reason, phase)))
            .await
    }

    async fn send_bulk_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        retry_delay: Duration,
    ) -> Result<(), ReplicationError> {
        self.send_bulk_unicast_inner(dst, topic, body, retry_delay, None)
            .await
    }

    async fn send_bulk_catchup_unicast(
        &self,
        dst: NodeIdentifier,
        topic: &str,
        body: StrictBody,
        retry_delay: Duration,
        reason: CatchupReason,
        phase: CatchupPhase,
    ) -> Result<(), ReplicationError> {
        self.send_bulk_unicast_inner(dst, topic, body, retry_delay, Some((reason, phase)))
            .await
    }

    fn acknowledge_bulk_unicast(&self, dst: NodeIdentifier, topic: &str, page: BulkPageIdentity) {
        self.bulk_pacer.acknowledge(dst, topic, page);
    }

    fn cancel_bulk_unicast(&self, dst: NodeIdentifier, topic: &str) {
        self.bulk_pacer.cancel(dst, topic);
    }

    async fn send_multicast(
        &self,
        dsts: &[NodeIdentifier],
        topic: &str,
        body: StrictBody,
    ) -> Result<(), ReplicationError> {
        if dsts.is_empty() {
            return Ok(());
        }
        let retained_logical_send = strict_retained_logical_send(topic, &body);
        let encode_started_at = Instant::now();
        let encoded = self.encode_strict_payload(topic, body);
        metrics::record_pipeline_stage(
            ReplicationPipelineKind::Strict,
            ReplicationPipelineStage::ProtobufEncode,
            encode_started_at.elapsed(),
        );
        let bytes = encoded?;
        self.overlay
            .send_multicast_on_lane_with_routing_metric_and_options(
                dsts,
                STRICT_CONTROL_LANE,
                REPLICATION_SERVICE_TAG,
                ServiceLevel::Reliable,
                RoutingMetric::ReliableCost,
                STRICT_REPLICATION_MESSAGE_CLASS,
                bytes,
                strict_replication_transport_options(false, self.transport_ttl(dsts))
                    .retain_logical_send(retained_logical_send),
            )
            .await?;
        Ok(())
    }

    async fn send_broadcast(&self, topic: &str, body: StrictBody) -> Result<(), ReplicationError> {
        let dsts = self.alive_members();
        self.send_multicast(&dsts, topic, body).await
    }

    fn encoded_strict_payload_len(
        &self,
        topic: &str,
        body: &StrictBody,
    ) -> Result<usize, ReplicationError> {
        self.encoded_v2_strict_payload_len(topic, body)
    }

    fn encoded_v2_strict_payload_len(
        &self,
        topic: &str,
        body: &StrictBody,
    ) -> Result<usize, ReplicationError> {
        // Fail closed on unavailable or oversized local proof material, but
        // never perform a real signature for a readiness/size query. Identity
        // metadata is cached when the transport loads its key and certificate.
        encoded_v2_strict_payload_len_with_provider(&self.overlay, topic, body)
    }

    fn alive_members(&self) -> Vec<NodeIdentifier> {
        self.protocol_snapshot()
            .targets
            .into_iter()
            .map(|target| target.node)
            .collect()
    }

    fn strict_participant_count(&self) -> usize {
        self.reconcile_known_participants();
        self.known_participants.lock().len()
    }

    fn strict_participant_incarnations(&self) -> Vec<(NodeIdentifier, u64)> {
        self.reconcile_known_participants();
        let mut electorate = self
            .known_participant_versions
            .lock()
            .iter()
            .map(|(node, (boot_epoch, _))| (*node, *boot_epoch))
            .collect::<Vec<_>>();
        electorate.sort_unstable_by_key(|(node, _)| *node);
        electorate
    }

    fn strict_replication_protocol_version(&self) -> u32 {
        let local = self.local_replication_capabilities();
        replication_protocol::strict_protocol_floor(
            &self.protocol_members(),
            local
                .strict_enabled()
                .then(|| local.strict_participant_protocol_version()),
        )
    }

    fn local_strict_replication_protocol_version(&self) -> u32 {
        self.participant_capability.protocol_version()
    }

    fn peer_strict_replication_protocol_version(&self, peer: NodeIdentifier) -> u32 {
        self.overlay
            .member(peer)
            .map(|member| {
                Self::member_replication_capabilities(&member).strict_participant_protocol_version()
            })
            .unwrap_or_default()
    }

    fn strict_protocol_snapshot(&self) -> StrictProtocolSnapshot {
        self.protocol_snapshot()
    }

    fn unsupported_active_protocol_peers(&self, required_version: u32) -> usize {
        self.reconcile_known_participants();
        let local_node = self.overlay.local_node_id();
        self.known_participant_versions
            .lock()
            .iter()
            .filter(|(node, (_, version))| **node != local_node && *version < required_version)
            .count()
    }

    fn strict_recovery_v8_ready(&self) -> bool {
        if self.participant_capability.protocol_version() < STRICT_PROTOCOL_VERSION_V8 {
            return false;
        }
        self.reconcile_known_participants();
        self.known_participant_versions
            .lock()
            .values()
            .all(|(_, version)| *version >= STRICT_PROTOCOL_VERSION_V8)
    }

    fn strict_protocol_state_dir(&self) -> Option<PathBuf> {
        self.overlay.persistence_dir()
    }

    fn current_protocol_prerequisites_ready(
        &self,
        topic: &str,
        strict_max_catchup_bytes: usize,
    ) -> bool {
        let local_budget = self.overlay.max_replication_payload_bytes();
        if local_budget < repl_proto::STRICT_V2_MAX_REPLICATION_PAYLOAD_BYTES {
            return false;
        }
        v2_control_prerequisite_bodies(self.overlay.local_node_id())
            .into_iter()
            .all(|body| {
                self.encoded_v2_strict_payload_len(topic, &body)
                    .is_ok_and(|encoded_len| {
                        v2_prerequisite_payload_fits(
                            local_budget,
                            strict_max_catchup_bytes,
                            encoded_len,
                        )
                    })
            })
    }

    fn max_replication_payload_bytes(&self) -> usize {
        self.overlay.max_replication_payload_bytes()
    }

    fn report_strict_replication_repository_capability_loss(&self) {
        self.participant_capability
            .report_repository_capability_loss();
    }

    fn member_boot_epoch(&self, node: NodeIdentifier) -> Option<u64> {
        if node == self.overlay.local_node_id() {
            Some(self.overlay.local_boot_epoch())
        } else {
            self.overlay.member(node).map(|member| member.boot_epoch())
        }
    }

    fn has_route(&self, dst: NodeIdentifier, level: ServiceLevel) -> bool {
        self.overlay.has_route(dst, level)
    }

    fn has_live_route(&self, dst: NodeIdentifier, level: ServiceLevel) -> bool {
        self.overlay.has_live_route(dst, level)
    }

    fn edge_rtt_snapshot(&self) -> Vec<Duration> {
        self.overlay.edge_rtt_snapshot()
    }

    fn route_rtt(&self, dst: NodeIdentifier) -> Option<Duration> {
        self.overlay.route_latency_with_metric(
            dst,
            ServiceLevel::Reliable,
            RoutingMetric::ReliableCost,
        )
    }
}

pub(super) fn replication_bulk_backpressure(error: &crate::overlay::OverlayError) -> bool {
    matches!(
        error,
        crate::overlay::OverlayError::Send(shitspeak_s2s_transport::SendError::Backpressure { .. })
    )
}

// ---------- State machine ----------

pub(crate) struct Proposal {
    pub op_msgpack: Bytes,
    pub ts_propose: u64,
    pub acks: HashMap<NodeIdentifier, u64>, // ack_node -> ts_local
    pub target_set: HashSet<NodeIdentifier>,
    pub(super) target_epochs: HashMap<NodeIdentifier, u64>,
    pub(super) invalid_targets: HashSet<NodeIdentifier>,
    pub accepted_waker: Option<oneshot::Sender<()>>,
    pub waker: Option<oneshot::Sender<Result<u64, ReplicationError>>>,
    pub committed: bool,
    pub protocol_version: u32,
    pub accept_acks: HashMap<NodeIdentifier, bool>,
    pub accept_started: bool,
    /// The immutable phase-two value emitted after the phase-one fast quorum.
    /// V2 retransmission must retain this exact body rather than rebuilding it
    /// from a later logical clock.
    pub(super) phase_two_accept: Option<StrictAccept>,
    #[cfg(any(test, feature = "test-support"))]
    pub(super) phase_two_retry_attempts: usize,
    #[cfg(any(test, feature = "test-support"))]
    pub(super) phase_two_floor_pauses: usize,
    pub started_at: Instant,
    /// Permit released when this proposal is removed from `proposals`.
    pub _permit: OwnedSemaphorePermit,
}

/// A caller-visible proposal that expired before a terminal decision. The
/// caller is released immediately, while an unresolved v2 fence is handed to
/// the durable terminal-resolution path after the state lock is released.
pub(crate) struct ExpiredProposal {
    op_id: OpId,
    waker: Option<oneshot::Sender<Result<u64, ReplicationError>>>,
    needs_v2_resolution: bool,
}

pub(crate) struct BufferedOp {
    pub op_msgpack: Bytes,
    pub ts_final: u64,
    pub op_id: OpId,
    buffered_at: Instant,
}

pub(crate) type BufferKey = (u64, OpId); // (ts_final, op_id)

pub(crate) const HISTORY_ELECTION_SNAPSHOT_TOKEN: u64 = u64::MAX;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct HistoryRank {
    pub version: u64,
    pub freshness: i64,
    pub runtime_started_at: u64,
    pub node_id: NodeIdentifier,
    pub terminal_repository_base_version: u64,
}

fn bootstrap_reachable_peers(net: &dyn StrictNet, self_id: NodeIdentifier) -> Vec<NodeIdentifier> {
    net.alive_members()
        .into_iter()
        // A logical route can outlive a broken first-hop transport while the
        // link-state view converges. Bootstrap must not wait for a probe sent
        // through such a route: it would pin the election until its coarse
        // timeout even though the remaining live peers have already replied.
        .filter(|node| {
            *node != self_id
                && replication_protocol::strict_participant_version_supported(
                    net.peer_strict_replication_protocol_version(*node),
                )
                && net.has_live_route(*node, ServiceLevel::Reliable)
        })
        .collect()
}

impl HistoryRank {
    pub fn local<R: StrictReplicable>(rt: &StrictRuntime<R>) -> Self {
        let metadata = rt.repo.history_metadata();
        Self::from_metadata(metadata, rt.boot_epoch, rt.self_id)
    }

    pub fn from_metadata(
        metadata: HistoryMetadata,
        runtime_started_at: u64,
        node_id: NodeIdentifier,
    ) -> Self {
        Self {
            version: metadata.version,
            freshness: metadata.freshness,
            runtime_started_at,
            node_id,
            terminal_repository_base_version: 0,
        }
    }

    pub fn beats(self, other: Self) -> bool {
        (
            self.version,
            self.freshness,
            std::cmp::Reverse(self.runtime_started_at),
            std::cmp::Reverse(self.node_id),
        ) > (
            other.version,
            other.freshness,
            std::cmp::Reverse(other.runtime_started_at),
            std::cmp::Reverse(other.node_id),
        )
    }
}

fn foreign_lineage_representation_order(
    remote_rank: HistoryRank,
    remote_generation: u64,
    local_rank: HistoryRank,
    local_generation: u64,
) -> std::cmp::Ordering {
    let repository_metadata_ties =
        (remote_rank.version, remote_rank.freshness) == (local_rank.version, local_rank.freshness);
    if repository_metadata_ties {
        remote_rank
            .terminal_repository_base_version
            .cmp(&local_rank.terminal_repository_base_version)
            .then_with(|| remote_generation.cmp(&local_generation))
            .then_with(|| {
                remote_rank
                    .beats(local_rank)
                    .cmp(&local_rank.beats(remote_rank))
            })
    } else {
        remote_generation.cmp(&local_generation).then_with(|| {
            remote_rank
                .beats(local_rank)
                .cmp(&local_rank.beats(remote_rank))
        })
    }
}

fn history_probe_candidate_beats(
    candidate: HistoryRank,
    candidate_terminal_populated: bool,
    current: HistoryRank,
    current_terminal_populated: bool,
) -> bool {
    if (candidate.version, candidate.freshness) == (current.version, current.freshness)
        && candidate_terminal_populated != current_terminal_populated
    {
        candidate_terminal_populated
    } else {
        candidate.beats(current)
    }
}

