    #[test]
    fn strict_transport_ttl_is_rtt_aware_and_bounded() {
        let cfg = ReplicationConfig::default();
        assert!(matches!(
            STRICT_REPLICATION_MESSAGE_CLASS,
            MessageClass::Regular
        ));
        let ttl = |rtt| {
            strict_transport_ttl(
                rtt,
                cfg.strict_transport_ttl_min(),
                cfg.strict_transport_ttl_max(),
                cfg.strict_consensus_rtt_margin(),
            )
        };
        assert_eq!(ttl(None), Duration::from_secs(1));
        assert_eq!(
            ttl(Some(Duration::from_millis(50))),
            Duration::from_millis(500)
        );
        assert_eq!(
            ttl(Some(Duration::from_millis(700))),
            Duration::from_millis(800)
        );
        assert_eq!(ttl(Some(Duration::from_secs(2))), Duration::from_secs(1));
    }

    #[test]
    fn consensus_retries_follow_the_slowest_missing_route_rtt() {
        let cfg = ReplicationConfig::default();
        let net = MockNet::new(1, vec![1, 2, 3]);
        assert_eq!(max_route_rtt(net.as_ref(), &[]), RouteRttSet::Empty);
        assert_eq!(max_route_rtt(net.as_ref(), &[2]), RouteRttSet::Unknown);
        assert_eq!(
            consensus_retry_interval(net.as_ref(), &[2, 3], &cfg),
            cfg.strict_consensus_retry_max()
        );

        net.set_route_rtt(2, Duration::from_millis(100));
        assert_eq!(
            consensus_retry_interval(net.as_ref(), &[2, 3], &cfg),
            cfg.strict_consensus_retry_max()
        );
        net.set_route_rtt(3, Duration::from_millis(400));
        assert_eq!(
            max_route_rtt(net.as_ref(), &[2, 3]),
            RouteRttSet::Measured(Duration::from_millis(400))
        );
        assert_eq!(
            consensus_retry_interval(net.as_ref(), &[2, 3], &cfg),
            Duration::from_millis(900)
        );
        assert_eq!(
            consensus_retry_interval(net.as_ref(), &[2], &cfg),
            cfg.strict_consensus_retry_min()
        );

        net.set_route_rtt(3, Duration::from_secs(2));
        assert_eq!(
            consensus_retry_interval(net.as_ref(), &[3], &cfg),
            cfg.strict_consensus_retry_max()
        );
    }

    #[tokio::test]
    async fn consensus_retry_uses_one_regular_multicast_and_broadcasts_only_on_failure() {
        let net = MockNet::new(1, vec![1, 2, 3]);
        let body = StrictBody::ProposeV1(StrictProposeV1 {
            coord_node: 1,
            op_id_hi: 1,
            op_id_lo: 2,
            protocol_version: STRICT_PROTOCOL_VERSION_V2,
            ..Default::default()
        });

        send_retry_multicast_with_broadcast(net.as_ref(), &[2, 3], "channels", body.clone())
            .await
            .unwrap();
        let sends = net.drain_strict_send_observations();
        assert_eq!(sends.len(), 1);
        assert_eq!(sends[0].lane, StrictSendLane::Ordinary);
        assert_eq!(sends[0].target, StrictSendTarget::Multicast(vec![2, 3]));
        assert_eq!(sends[0].outcome, StrictSendOutcome::Sent);

        net.set_fail_strict_multicasts(true);
        assert!(
            send_retry_multicast_with_broadcast(net.as_ref(), &[2, 3], "channels", body.clone(),)
                .await
                .is_err()
        );
        let sends = net.drain_strict_send_observations();
        assert_eq!(sends.len(), 1);
        assert_eq!(sends[0].lane, StrictSendLane::Ordinary);
        assert_eq!(sends[0].target, StrictSendTarget::Multicast(vec![2, 3]));
        assert_eq!(sends[0].outcome, StrictSendOutcome::InjectedFailure);

        net.set_fail_strict_multicasts(false);
        net.fail_strict_unicasts_to([2]);
        send_retry_multicast_with_broadcast(net.as_ref(), &[2], "channels", body)
            .await
            .unwrap();
        let sends = net.drain_strict_send_observations();
        assert_eq!(sends.len(), 2);
        assert_eq!(sends[0].lane, StrictSendLane::Ordinary);
        assert_eq!(sends[0].target, StrictSendTarget::Unicast(2));
        assert_eq!(sends[0].outcome, StrictSendOutcome::InjectedFailure);
        assert_eq!(sends[1].lane, StrictSendLane::Ordinary);
        assert_eq!(sends[1].target, StrictSendTarget::Broadcast);
        assert_eq!(sends[1].outcome, StrictSendOutcome::Sent);
    }

    #[test]
    fn every_production_overlay_enqueue_uses_the_strict_transport_policy() {
        const SOURCE: &str = include_str!("runtime.rs");
        const ENQUEUE_METHODS: [&str; 2] = [
            ".send_unicast_on_lane_with_routing_metric_and_options(",
            ".send_multicast_on_lane_with_routing_metric_and_options(",
        ];

        let production = SOURCE
            .split_once("// ---------- Unit tests ----------")
            .expect("runtime unit-test delimiter must remain present")
            .0;
        assert!(!production.contains("MessageClass::HighPriority"));
        assert!(!production.contains("send_redundant_multicast"));
        assert!(!include_str!("propose.rs").contains("send_redundant_multicast"));

        let mut enqueue_count = 0usize;
        for method in ENQUEUE_METHODS {
            let mut remainder = production;
            while let Some(method_start) = remainder.find(method) {
                let invocation = &remainder[method_start..];
                let mut depth = 0usize;
                let mut invocation_end = None;
                for (offset, character) in invocation.char_indices() {
                    match character {
                        '(' => depth += 1,
                        ')' => {
                            depth = depth
                                .checked_sub(1)
                                .expect("enqueue invocation parentheses must balance");
                            if depth == 0 {
                                invocation_end = Some(offset + character.len_utf8());
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                let invocation = &invocation
                    [..invocation_end.expect("enqueue invocation must have a closing parenthesis")];
                assert!(
                    invocation.contains("STRICT_REPLICATION_MESSAGE_CLASS"),
                    "strict overlay enqueue bypasses the shared Regular queue policy: {invocation}"
                );
                assert!(
                    [
                        "STRICT_CONTROL_LANE",
                        "STRICT_CONTROL_ALTERNATE_LANE",
                        "STRICT_BULK_LANE",
                    ]
                    .iter()
                    .any(|lane| invocation.contains(lane)),
                    "strict overlay enqueue bypasses end-to-end ACK retention: {invocation}"
                );
                assert!(
                    invocation.contains("strict_replication_transport_options("),
                    "strict overlay enqueue bypasses the shared TTL policy: {invocation}"
                );
                enqueue_count += 1;
                remainder = &remainder[method_start + invocation.len()..];
            }
        }

        assert_eq!(
            enqueue_count, 5,
            "audit new or removed strict overlay enqueue sites and update this sentinel"
        );
    }

    #[test]
    fn p95_clock_tick_picks_correct_index_via_nearest_rank() {
        let cfg = ReplicationConfig::default();
        // n=20, p=0.95: idx_one_based = ceil(19.0) = 19, idx = 18.
        // Samples 50..=1000ms by 50: samples[18] = 950ms.
        let samples: Vec<Duration> = (1..=20).map(|i| Duration::from_millis(i * 50)).collect();
        let p95 = p95_clock_tick_interval(&samples, &cfg);
        assert_eq!(p95, Duration::from_millis(950));
        // n=100, samples 1..=100ms: idx_one_based = 95, idx = 94.
        // samples[94] = 95ms, clamped up to min_clock_tick().
        let samples: Vec<Duration> = (1..=100).map(Duration::from_millis).collect();
        let p95 = p95_clock_tick_interval(&samples, &cfg);
        assert_eq!(p95, cfg.min_clock_tick());
    }

    #[test]
    fn p95_clock_tick_clamps_to_min() {
        let cfg = ReplicationConfig::default();
        // All samples below min_clock_tick() ⇒ result clamped up.
        let samples = vec![Duration::from_millis(5); 10];
        assert_eq!(
            p95_clock_tick_interval(&samples, &cfg),
            cfg.min_clock_tick()
        );
    }

    #[test]
    fn p95_clock_tick_clamps_to_max() {
        let cfg = ReplicationConfig::default();
        // All samples above max_clock_tick() ⇒ result clamped down.
        let samples = vec![Duration::from_secs(30); 10];
        assert_eq!(
            p95_clock_tick_interval(&samples, &cfg),
            cfg.max_clock_tick()
        );
    }

    #[test]
    fn p95_clock_tick_ignores_single_outlier_above_p95_index() {
        let cfg = ReplicationConfig::default();
        // 19 fast edges + 1 slow outlier. n=20, idx = 18.
        // After sort, samples[18] is the last fast edge, samples[19] is the
        // outlier. The outlier sits at p100, NOT p95 — so p95 == 150ms.
        let mut samples: Vec<Duration> = vec![Duration::from_millis(150); 19];
        samples.push(Duration::from_secs(2));
        let p95 = p95_clock_tick_interval(&samples, &cfg);
        assert_eq!(p95, Duration::from_millis(150));

        // 39 fast edges + 1 outlier (n=40). idx = 37, still in the fast block.
        let mut samples: Vec<Duration> = vec![Duration::from_millis(150); 39];
        samples.push(Duration::from_secs(2));
        let p95 = p95_clock_tick_interval(&samples, &cfg);
        assert_eq!(p95, Duration::from_millis(150));
    }

