    #[test]
    fn admission_cut_waits_for_every_equal_timestamp_delivery() {
        let mut state = StrictState::new();
        state.finish_history_election();
        state.admission_tracking_started = true;
        let first = (1, 1);
        let second = (1, 2);
        assert!(state.mark_committed(first, 101));
        assert!(state.mark_committed(second, 101));
        state.buffer_commit(first, 101, Bytes::new());
        state.buffer_commit(second, 101, Bytes::new());
        state.reconcile_peer_admissions(1, &[(1, 1), (2, 3)]);
        let drained = state.drain_deliverable(101);
        state.mark_delivering_commits(&drained);

        state.finish_delivering_commit(first);
        state.delivered_high_water = 101;
        state.freeze_ready_admission_cuts(HistoryMetadata {
            version: 1,
            freshness: 1,
        });
        assert_eq!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::AwaitingLocalCut { barrier_ts: 101 }
        );

        state.finish_delivering_commit(second);
        state.freeze_ready_admission_cuts(HistoryMetadata {
            version: 2,
            freshness: 2,
        });
        assert!(matches!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::AwaitingPeer {
                required_history: HistoryMetadata { version: 2, .. },
                ..
            }
        ));
    }

    #[test]
    fn admission_requires_history_and_clock_strictly_above_barrier() {
        let required_history = HistoryMetadata {
            version: 8,
            freshness: 13,
        };
        let mut state = StrictState::new();
        state.finish_history_election();
        state.admission_tracking_started = true;
        state.delivered_high_water = 101;
        state.reconcile_peer_admissions(1, &[(1, 1), (2, 9), (3, 4)]);
        state.freeze_ready_admission_cuts(required_history);

        assert!(!state.observe_admission_history(2, 9, required_history));
        state.observe_admission_clock(3, 4, 102);
        assert_eq!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::AwaitingPeer {
                required_history,
                clock_gt: 101,
                history_ready: true,
                clock_ready: false,
            }
        );
        assert_eq!(
            state.peer_admissions[&3].phase,
            PeerAdmissionPhase::AwaitingPeer {
                required_history,
                clock_gt: 101,
                history_ready: false,
                clock_ready: true,
            }
        );

        state.observe_admission_clock(2, 9, 101);
        assert!(!matches!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::Admitted
        ));
        state.observe_admission_clock(2, 9, 102);
        assert_eq!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::Admitted
        );
    }

    #[tokio::test]
    async fn one_v6_clock_probe_round_trip_crosses_an_asymmetric_admission_barrier() {
        let requester_net = MockNet::new(1, vec![1, 2]);
        requester_net.set_epoch(1, 11);
        requester_net.set_epoch(2, 22);
        enable_v8_capabilities(&requester_net, [2]);
        let requester = StrictRuntime::new(
            CountingStrictRepo::new(),
            1,
            11,
            "channels".to_owned(),
            requester_net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        requester.finish_history_election_for_test();
        {
            let mut state = requester.state.lock();
            state.clock = 10_000;
            state.delivered_high_water = 10_000;
        }
        requester.seed_membership_snapshot([
            MemberIncarnation::new(1, 11),
            MemberIncarnation::new(2, 22),
        ]);
        {
            let mut state = requester.state.lock();
            state.freeze_ready_admission_cuts(HistoryMetadata {
                version: 0,
                freshness: 0,
            });
            assert!(!state.observe_admission_history(
                2,
                22,
                HistoryMetadata {
                    version: 0,
                    freshness: 0,
                },
            ));
            assert_eq!(
                state.peer_admissions[&2].phase,
                PeerAdmissionPhase::AwaitingPeer {
                    required_history: HistoryMetadata {
                        version: 0,
                        freshness: 0,
                    },
                    clock_gt: 10_000,
                    history_ready: true,
                    clock_ready: false,
                }
            );
        }

        let responder_net = MockNet::new(2, vec![1, 2]);
        responder_net.set_epoch(1, 11);
        responder_net.set_epoch(2, 22);
        enable_v8_capabilities(&responder_net, [1]);
        let responder = StrictRuntime::new(
            CountingStrictRepo::new(),
            2,
            22,
            "channels".to_owned(),
            responder_net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        responder.finish_history_election_for_test();
        responder.seed_membership_snapshot([
            MemberIncarnation::new(1, 11),
            MemberIncarnation::new(2, 22),
        ]);
        responder
            .state
            .lock()
            .peer_admissions
            .get_mut(&1)
            .unwrap()
            .phase = PeerAdmissionPhase::Admitted;
        assert_eq!(responder.state.lock().clock, 0);

        super::super::catchup::request_v3_clock_probe(
            &requester,
            2,
            StrictCatchupReason::Admission,
        )
        .await;
        let request = requester_net
            .drain_captures()
            .into_iter()
            .find_map(|frame| match frame {
                CapturedFrame::StrictUnicast {
                    dst: 2,
                    body: StrictBody::ClockProbeReq(request),
                    ..
                } => Some(request),
                _ => None,
            })
            .expect("clock probe request");
        super::super::catchup::recv_v3_clock_probe_req(&responder, 1, 11, request).await;
        let response = responder_net
            .drain_captures()
            .into_iter()
            .find_map(|frame| match frame {
                CapturedFrame::StrictUnicast {
                    dst: 1,
                    body: StrictBody::ClockProbeResp(response),
                    ..
                } => Some(response),
                _ => None,
            })
            .expect("clock probe response");
        super::super::catchup::recv_v3_clock_probe_resp(&requester, 2, 22, response);

        assert!(
            requester.peer_incarnation_is_admitted(2, 22),
            "one correlated RTT must raise the restarted responder past the frozen barrier"
        );
        request_admission_probes(&requester).await;
        assert!(
            requester_net.drain_captures().is_empty(),
            "an admitted incarnation must not retain periodic admission traffic"
        );
    }

    #[tokio::test]
    async fn one_v8_clock_probe_round_trip_avoids_admission_retries() {
        const BARRIER: u64 = 10_000;

        let requester_net = MockNet::new(1, vec![1, 2]);
        requester_net.set_epoch(1, 11);
        requester_net.set_epoch(2, 22);
        enable_v8_capabilities(&requester_net, [2]);
        requester_net.set_alive(vec![1, 2]);
        requester_net.set_live_reliable_routes([1, 2]);
        let requester = StrictRuntime::new(
            CountingStrictRepo::new(),
            1,
            11,
            "channels".to_owned(),
            requester_net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        requester.finish_history_election_for_test();
        {
            let mut state = requester.state.lock();
            state.clock = BARRIER;
            state.delivered_high_water = BARRIER;
        }
        requester.seed_membership_snapshot([
            MemberIncarnation::new(1, 11),
            MemberIncarnation::new(2, 22),
        ]);
        {
            let mut state = requester.state.lock();
            state.freeze_ready_admission_cuts(HistoryMetadata {
                version: 0,
                freshness: 0,
            });
            assert!(!state.observe_admission_history(
                2,
                22,
                HistoryMetadata {
                    version: 0,
                    freshness: 0,
                },
            ));
        }

        let responder_net = MockNet::new(2, vec![1, 2]);
        responder_net.set_epoch(1, 11);
        responder_net.set_epoch(2, 22);
        enable_v8_capabilities(&responder_net, [1]);
        let responder = StrictRuntime::new(
            CountingStrictRepo::new(),
            2,
            22,
            "channels".to_owned(),
            responder_net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        responder.finish_history_election_for_test();
        responder.seed_membership_snapshot([
            MemberIncarnation::new(1, 11),
            MemberIncarnation::new(2, 22),
        ]);
        responder
            .state
            .lock()
            .peer_admissions
            .get_mut(&1)
            .unwrap()
            .phase = PeerAdmissionPhase::Admitted;

        request_admission_probes(&requester).await;
        let captures = requester_net.drain_captures();
        let request = captures
            .into_iter()
            .find_map(|frame| match frame {
                CapturedFrame::StrictUnicast {
                    dst: 2,
                    body: StrictBody::ClockProbeReq(request),
                    ..
                } => Some(request),
                _ => None,
            })
            .expect("admission clock probe");
        super::super::catchup::recv_v3_clock_probe_req(&responder, 1, 11, request).await;
        let response = responder_net
            .drain_captures()
            .into_iter()
            .find_map(|frame| match frame {
                CapturedFrame::StrictUnicast {
                    dst: 1,
                    body: StrictBody::ClockProbeResp(response),
                    ..
                } => Some(response),
                _ => None,
            })
            .expect("clock probe response");
        assert!(response.src_clock > BARRIER);
        super::super::catchup::recv_v3_clock_probe_resp(&requester, 2, 22, response);

        assert!(requester.peer_incarnation_is_admitted(2, 22));
        request_admission_probes(&requester).await;
        assert!(
            requester_net.drain_captures().is_empty(),
            "one v8 probe round trip must complete admission without a retry storm",
        );
    }

    #[test]
    fn clock_probe_requester_clock_waits_for_the_v6_cluster_floor() {
        const REQUESTER_CLOCK: u64 = 10_000;

        let net = MockNet::new(1, vec![1, 2]);
        net.set_epoch(1, 11);
        net.set_epoch(2, 22);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V5);
        net.set_local_strict_replication_protocol_version(Some(STRICT_PROTOCOL_VERSION_V6));
        net.set_peer_strict_replication_protocol_version(2, STRICT_PROTOCOL_VERSION_V6);
        let runtime = StrictRuntime::new(
            CountingStrictRepo::new(),
            1,
            11,
            "channels".to_owned(),
            net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        runtime.state.lock().clock = REQUESTER_CLOCK;

        assert_eq!(runtime.v3_clock_probe_requester_clock(), 0);
        runtime.state.lock().clock = 0;
        assert_eq!(
            runtime.advance_v3_clock_probe(2, 22, REQUESTER_CLOCK),
            1,
            "a v5 cluster must ignore an injected requester clock",
        );

        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V6);
        runtime.state.lock().clock = REQUESTER_CLOCK;
        assert_eq!(runtime.v3_clock_probe_requester_clock(), REQUESTER_CLOCK,);
        runtime.state.lock().clock = 0;
        assert_eq!(
            runtime.advance_v3_clock_probe(2, 22, REQUESTER_CLOCK),
            REQUESTER_CLOCK + 1,
        );
    }

    #[test]
    fn admission_proofs_are_epoch_scoped() {
        let required_history = HistoryMetadata {
            version: 3,
            freshness: 7,
        };
        let mut state = StrictState::new();
        state.finish_history_election();
        state.admission_tracking_started = true;
        state.delivered_high_water = 50;
        state.reconcile_peer_admissions(1, &[(1, 1), (2, 2)]);
        state.freeze_ready_admission_cuts(required_history);

        assert!(!state.observe_admission_history(2, 1, required_history));
        state.observe_admission_clock(2, 1, 51);
        assert_eq!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::AwaitingPeer {
                required_history,
                clock_gt: 50,
                history_ready: false,
                clock_ready: false,
            }
        );

        assert!(!state.observe_admission_history(2, 2, required_history));
        state.observe_admission_clock(2, 1, u64::MAX);
        assert!(!matches!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::Admitted
        ));
        state.observe_admission_clock(2, 2, 51);
        assert_eq!(
            state.peer_admissions[&2].phase,
            PeerAdmissionPhase::Admitted
        );
    }

