    #[tokio::test(start_paused = true)]
    async fn recovery_commit_retry_waits_for_route_rtt_rto() {
        let net = MockNet::new(1, vec![1, 2]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        net.set_route_rtt(2, Duration::from_millis(400));
        let cfg = Arc::new(
            ReplicationConfig::default()
                .with_strict_consensus_retry_min(Duration::from_millis(50))
                .with_strict_consensus_retry_max(Duration::from_secs(2))
                .with_strict_consensus_rtt_margin(Duration::from_millis(100))
                .with_strict_consensus_retry_jitter_pct(0),
        );
        let shutdown = CancellationToken::new();
        let op_id = make_op_id(1, 1, 77);
        let body = StrictBody::RecoveryCommit(StrictRecoveryCommit {
            takeover_node: 1,
            coord_node: 1,
            op_id_hi: op_id.0,
            op_id_lo: op_id.1,
            ..Default::default()
        });

        spawn_recovery_commit_repair_retries(
            net.clone(),
            shutdown.clone(),
            "channels".to_owned(),
            1,
            op_id,
            HashSet::from([1, 2]),
            body,
            cfg,
            Duration::from_secs(2),
        );
        tokio::task::yield_now().await;

        tokio::time::advance(Duration::from_millis(899)).await;
        tokio::task::yield_now().await;
        assert!(net.drain_strict_send_observations().is_empty());

        tokio::time::advance(Duration::from_millis(1)).await;
        tokio::task::yield_now().await;
        let sends = net.drain_strict_send_observations();
        assert_eq!(sends.len(), 1);
        assert_eq!(sends[0].lane, StrictSendLane::Ordinary);
        assert_eq!(sends[0].target, StrictSendTarget::Unicast(2));
        assert_eq!(sends[0].outcome, StrictSendOutcome::Sent);
        shutdown.cancel();
    }

    #[tokio::test(start_paused = true)]
    async fn recovery_commit_retry_never_broadcasts_to_escape_a_failed_target() {
        let net = MockNet::new(1, vec![1, 2, 3]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        net.set_peer_strict_replication_protocol_version(2, STRICT_PROTOCOL_VERSION_V8);
        net.set_peer_strict_replication_protocol_version(3, STRICT_PROTOCOL_VERSION_V7);
        net.fail_strict_unicasts_to([2]);
        let cfg = Arc::new(
            ReplicationConfig::default()
                .with_strict_consensus_retry_min(Duration::from_millis(50))
                .with_strict_consensus_retry_max(Duration::from_millis(50))
                .with_strict_consensus_rtt_margin(Duration::ZERO)
                .with_strict_consensus_retry_jitter_pct(0),
        );
        let shutdown = CancellationToken::new();
        let op_id = make_op_id(1, 1, 78);
        let body = StrictBody::RecoveryCommit(StrictRecoveryCommit {
            takeover_node: 1,
            coord_node: 1,
            op_id_hi: op_id.0,
            op_id_lo: op_id.1,
            ..Default::default()
        });

        spawn_recovery_commit_repair_retries(
            net.clone(),
            shutdown.clone(),
            "channels".to_owned(),
            1,
            op_id,
            HashSet::from([1, 2]),
            body,
            cfg,
            Duration::from_millis(200),
        );
        tokio::task::yield_now().await;
        tokio::time::advance(Duration::from_millis(50)).await;
        tokio::task::yield_now().await;

        assert!(
            net.drain_captures().is_empty(),
            "a failed targeted recovery retry must not broadcast to deprecated participants"
        );
        let sends = net.drain_strict_send_observations();
        assert_eq!(sends.len(), 1);
        assert_eq!(sends[0].target, StrictSendTarget::Unicast(2));
        assert_eq!(sends[0].outcome, StrictSendOutcome::InjectedFailure);
        shutdown.cancel();
    }

    #[test]
    fn make_ballot_orders_by_node_then_attempt() {
        let a = make_ballot(2, 1);
        let b = make_ballot(2, 5);
        let c = make_ballot(3, 0);
        assert!(a < b, "same node, higher attempt wins");
        assert!(b < c, "higher node id outranks");
    }

    #[test]
    fn try_promise_is_monotonic() {
        let mut s = StrictState::new();
        let op_id: OpId = (1, 1);
        assert!(s.try_promise(op_id, 10));
        assert_eq!(s.recovery_promises[&op_id], 10);
        // Lower or equal ballots are rejected (no update, returns false).
        assert!(!s.try_promise(op_id, 5));
        assert!(!s.try_promise(op_id, 10));
        assert_eq!(s.recovery_promises[&op_id], 10);
        // Strictly higher succeeds.
        assert!(s.try_promise(op_id, 11));
        assert_eq!(s.recovery_promises[&op_id], 11);
    }

    #[test]
    fn mark_committed_dedups_repeat_calls() {
        let mut s = StrictState::new();
        let op_id: OpId = (7, 7);
        assert!(s.mark_committed(op_id, 100));
        assert_eq!(s.committed_ts_final[&op_id], 100);
        // Second call: false (already marked); does NOT overwrite ts_final.
        assert!(!s.mark_committed(op_id, 999));
        assert_eq!(s.committed_ts_final[&op_id], 100);
    }

    #[test]
    fn mark_committed_clears_pending_propose() {
        let mut s = StrictState::new();
        let op_id: OpId = (1, 2);
        s.record_pending_propose(op_id, 5, Bytes::from_static(b"x"), 33, Instant::now());
        assert!(s.pending_proposes.contains_key(&op_id));
        s.mark_committed(op_id, 50);
        assert!(!s.pending_proposes.contains_key(&op_id));
    }

