    #[test]
    fn history_election_uses_a_longer_timeout_for_snapshot_transfer() {
        let mut state = StrictState::new();
        state.begin_history_election([2]);
        assert!(state.history_election_timed_out(
            Instant::now() + Duration::from_millis(600),
            Duration::from_millis(500),
            Duration::from_secs(20),
        ));
        let local_rank = HistoryRank {
            version: 8,
            freshness: 0,
            runtime_started_at: 100,
            node_id: 1,
            terminal_repository_base_version: 0,
        };
        let remote_rank = HistoryRank {
            version: 9,
            freshness: 1,
            runtime_started_at: 200,
            node_id: 2,
            terminal_repository_base_version: 0,
        };
        assert!(matches!(
            state.record_history_probe_response(2, remote_rank, local_rank),
            HistoryProbeResponseOutcome::FetchSnapshot(_)
        ));

        assert!(
            !state.history_election_timed_out(
                Instant::now() + Duration::from_millis(600),
                Duration::from_millis(500),
                Duration::from_secs(20),
            ),
            "terminal synchronization and snapshot transfer need a longer timeout than probing"
        );
    }

    #[test]
    fn history_election_restarts_snapshot_timeout_after_terminal_sync() {
        let mut state = StrictState::new();
        state.begin_history_election([2]);
        let local_rank = HistoryRank {
            version: 8,
            freshness: 0,
            runtime_started_at: 100,
            node_id: 1,
            terminal_repository_base_version: 0,
        };
        let remote_rank = HistoryRank {
            version: 9,
            freshness: 1,
            runtime_started_at: 200,
            node_id: 2,
            terminal_repository_base_version: 0,
        };
        let HistoryProbeResponseOutcome::FetchSnapshot(request) =
            state.record_history_probe_response(2, remote_rank, local_rank)
        else {
            panic!("remote rank should win");
        };

        let snapshot_timeout = Duration::from_secs(20);
        let now = Instant::now();
        match &mut state.history_election_phase {
            HistoryElectionPhase::FetchingSnapshot { started_at, .. } => {
                // The elected source spent the initial transfer lease
                // synchronizing its terminal checkpoint before repository
                // transfer could begin.
                *started_at = now - snapshot_timeout;
            }
            phase => panic!("expected elected snapshot fetch, got {phase:?}"),
        }
        assert!(state.history_election_timed_out(
            now,
            Duration::from_millis(500),
            snapshot_timeout,
        ));

        // Beginning the repository transfer must receive its own full lease;
        // otherwise terminal synchronization consumes the snapshot deadline.
        assert!(state.begin_history_election_snapshot_transfer(request));

        assert!(
            !state.history_election_timed_out(now, Duration::from_millis(500), snapshot_timeout,),
            "the repository transfer must not inherit the terminal-sync timeout"
        );
    }

    #[test]
    fn admission_proofs_back_off_independently_and_reset_for_changed_obligation() {
        let interval = Duration::from_millis(10);
        let (rt, _net, _repo) = v1_runtime(
            ReplicationConfig::default()
                .with_strict_bootstrap_retry_interval(interval)
                .with_strict_steady_state_catchup_interval(Duration::from_millis(80)),
        );
        let local_history = rt.repo.history_metadata();
        let probe = PendingAdmissionProbe {
            peer: 2,
            boot_epoch: 1,
            history_election_generation: 0,
            needs_history: true,
            needs_clock: true,
            required_history: local_history,
            clock_gt: 7,
        };
        assert_eq!(
            rt.admission_probes_due(probe, None),
            AdmissionProbesDue {
                history: true,
                clock: true,
            }
        );

        rt.admission_probe_schedules
            .lock()
            .get_mut(&2)
            .expect("admission probe schedule")
            .next_clock_at = Instant::now();
        let second_clock_attempt_started_at = Instant::now();
        assert_eq!(
            rt.admission_probes_due(probe, None),
            AdmissionProbesDue {
                history: false,
                clock: true,
            },
            "history backoff must not suppress clock progress",
        );

        let next_clock_at = rt
            .admission_probe_schedules
            .lock()
            .get(&2)
            .expect("admission probe schedule")
            .next_clock_at;
        assert!(
            next_clock_at >= second_clock_attempt_started_at + interval.saturating_mul(4),
            "an unchanged clock obligation must exponentially back off fresh nonces",
        );

        let changed_probe = PendingAdmissionProbe {
            required_history: HistoryMetadata {
                freshness: local_history.freshness.saturating_add(1),
                ..local_history
            },
            ..probe
        };
        assert_eq!(
            rt.admission_probes_due(changed_probe, None),
            AdmissionProbesDue {
                history: true,
                clock: true,
            },
            "a changed frozen obligation must retry immediately",
        );
    }

