    #[tokio::test]
    async fn strict_history_election_rearms_v3_winner_without_correlated_candidate() {
        let net = MockNet::new(1, vec![1, 2, 3]);
        enable_v8_capabilities(&net, [2, 3]);
        net.set_epoch(2, 1);
        net.set_epoch(3, 1);
        let repo = CountingStrictRepo::new();
        let rt = StrictRuntime::new(
            repo,
            1,
            100,
            "channels".to_owned(),
            net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        rt.try_bootstrap_catchup().await;

        let captures = net.drain_captures();
        assert_eq!(captures.len(), 2);
        let mut probe_dsts = Vec::new();
        for capture in &captures {
            let crate::replications::test_support::CapturedFrame::StrictUnicast {
                dst, body, ..
            } = capture
            else {
                panic!("unexpected capture: {capture:?}");
            };
            probe_dsts.push(*dst);
            let StrictBody::HistoryProbeReq(req) = body else {
                panic!("expected V4 history probe, got {body:?}");
            };
            assert_eq!(req.src_node, 1);
            assert_eq!(req.expected_responder_boot_epoch, 1);
            assert_ne!(req.request_nonce, 0);
            assert_eq!(req.reason, StrictCatchupReason::HistoryElection as i32);
        }
        probe_dsts.sort_unstable();
        assert_eq!(probe_dsts, vec![2, 3]);

        rt.recv_catchup_resp(2, strict_probe_resp(2, 10, 100, 40))
            .await;
        assert!(net.drain_captures().is_empty());

        rt.recv_catchup_resp(3, strict_probe_resp(3, 8, 999, 1))
            .await;

        let captures = net.drain_captures();
        assert!(
            captures.is_empty(),
            "a supported participant without an exact V3 candidate must never receive a legacy snapshot request: {captures:?}",
        );
        assert!(rt.state.lock().can_start_history_election());
    }

