    #[tokio::test]
    async fn terminal_fanout_retries_after_the_former_fixed_window() {
        let net = MockNet::new(1, vec![1, 2]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        let shutdown = CancellationToken::new();
        let body = StrictBody::Decision(StrictDecision {
            resolver_node: 1,
            ballot: NORMAL_ACCEPT_BALLOT,
            coord_node: 1,
            op_id_hi: make_op_id(1, 1, 135).0,
            op_id_lo: make_op_id(1, 1, 135).1,
            outcome: Some(StrictDecisionOutcome::Abort(StrictDecisionAbort {})),
            src_clock: 1,
            resolver_boot_epoch: 1,
            frozen_targets: vec![StrictFrozenTarget {
                node: 1,
                boot_epoch: 1,
            }],
            ..Default::default()
        });
        spawn_commit_fanout_retries(
            net.clone(),
            shutdown.clone(),
            "channels".to_owned(),
            1,
            make_op_id(1, 1, 135),
            vec![2],
            body.clone(),
            Arc::new(
                ReplicationConfig::default()
                    .with_strict_consensus_retry_min(Duration::from_millis(1))
                    .with_strict_consensus_retry_max(Duration::from_millis(1))
                    .with_strict_consensus_rtt_margin(Duration::ZERO),
            ),
            Duration::from_secs(1),
        );

        // Simulate an unavailable route for longer than the old 80-tick
        // fanout cap, then observe a fresh terminal decision retry after the
        // production repair cadence's backoff interval.
        tokio::time::sleep(Duration::from_millis(120)).await;
        net.drain_captures();
        let mut late_retry = None;
        for _ in 0..130 {
            tokio::time::sleep(Duration::from_millis(5)).await;
            late_retry = net
                .drain_captures()
                .into_iter()
                .find_map(|frame| match frame {
                    CapturedFrame::StrictMulticast {
                        dsts,
                        body: captured,
                        ..
                    } if dsts == vec![2] => Some(captured),
                    _ => None,
                });
            if late_retry.is_some() {
                break;
            }
        }
        shutdown.cancel();
        assert_eq!(
            late_retry.expect("terminal fanout must outlive the former fixed retry window"),
            body
        );
    }

    #[tokio::test(start_paused = true)]
    async fn terminal_fanout_retry_uses_route_rtt_and_exponential_backoff() {
        let net = MockNet::new(1, vec![1, 2]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        net.set_route_rtt(2, Duration::from_millis(100));
        let shutdown = CancellationToken::new();
        let op_id = make_op_id(1, 1, 136);
        let body = StrictBody::Decision(StrictDecision {
            resolver_node: 1,
            ballot: NORMAL_ACCEPT_BALLOT,
            coord_node: 1,
            op_id_hi: op_id.0,
            op_id_lo: op_id.1,
            outcome: Some(StrictDecisionOutcome::Abort(StrictDecisionAbort {})),
            src_clock: 1,
            resolver_boot_epoch: 1,
            ..Default::default()
        });
        let cfg = Arc::new(
            ReplicationConfig::default()
                .with_strict_consensus_retry_min(Duration::from_millis(50))
                .with_strict_consensus_retry_max(Duration::from_secs(1))
                .with_strict_consensus_rtt_margin(Duration::ZERO)
                .with_strict_consensus_retry_jitter_pct(0),
        );

        spawn_commit_fanout_retries(
            net.clone(),
            shutdown.clone(),
            "channels".to_owned(),
            1,
            op_id,
            vec![2],
            body.clone(),
            cfg,
            Duration::from_secs(2),
        );
        tokio::task::yield_now().await;

        tokio::time::advance(Duration::from_millis(199)).await;
        tokio::task::yield_now().await;
        assert!(net.drain_captures().is_empty());

        tokio::time::advance(Duration::from_millis(1)).await;
        tokio::task::yield_now().await;
        assert!(captured_terminal_replay(&net.drain_captures(), &body));

        tokio::time::advance(Duration::from_millis(399)).await;
        tokio::task::yield_now().await;
        assert!(net.drain_captures().is_empty());

        tokio::time::advance(Duration::from_millis(1)).await;
        tokio::task::yield_now().await;
        assert!(captured_terminal_replay(&net.drain_captures(), &body));
        shutdown.cancel();
    }

