    #[tokio::test]
    async fn imported_terminal_commit_at_current_repository_base_keeps_snapshots_available() {
        let repository_version = 9_525;
        let net = MockNet::new(1, vec![1, 2]);
        net.set_epoch(1, 1);
        net.set_epoch(2, 1);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        let repo = CountingStrictRepo::new();
        repo.state.lock().0 = repository_version;
        let rt = StrictRuntime::new(
            repo.clone(),
            1,
            1,
            "channels".to_owned(),
            net,
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        rt.finish_history_election_for_test();
        assert!(rt.begin_snapshot_capture().is_some());

        let op_id = make_op_id(2, 1, 74);
        assert!(
            rt.apply_catchup_terminal_commit_with_repository_base(
                StrictTerminalState {
                    coord_node: 2,
                    op_id_hi: op_id.0,
                    op_id_lo: op_id.1,
                    ballot: 1,
                    outcome: Some(StrictTerminalOutcome::Commit(StrictDecisionCommit {
                        ts_final: 74,
                        op_msgpack: Bytes::from(rmp_serde::to_vec(&174u64).unwrap()),
                    })),
                    resolver_node: 0,
                    resolver_boot_epoch: 0,
                    frozen_targets: Vec::new(),
                },
                repository_version,
            )
            .await,
            "the terminal commit must import at its already-present repository base"
        );

        assert_eq!(rt.repo.current_version(), repository_version);
        assert_eq!(
            rt.terminal_journal
                .lock()
                .await
                .get(op_id)
                .and_then(TerminalJournalRecord::required_repository_base_version),
            Some(repository_version),
            "the durable record must retain its repository dependency"
        );
        assert!(
            !rt.repository_base_required(),
            "a dependency equal to the current repository version is already satisfied"
        );
        assert!(
            rt.begin_snapshot_capture().is_some(),
            "an already-satisfied imported fence must not disable snapshot donation"
        );
    }

    #[tokio::test]
    async fn already_durable_terminal_commit_uses_its_strongest_repository_base() {
        let repository_version = 95;
        let net = MockNet::new(1, vec![1, 2]);
        net.set_epoch(1, 1);
        net.set_epoch(2, 1);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        let repo = CountingStrictRepo::new();
        repo.state.lock().0 = repository_version;
        let rt = StrictRuntime::new(
            repo,
            1,
            1,
            "channels".to_owned(),
            net,
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        rt.finish_history_election_for_test();

        let op_id = make_op_id(2, 1, 75);
        let terminal = StrictTerminalState {
            coord_node: 2,
            op_id_hi: op_id.0,
            op_id_lo: op_id.1,
            ballot: 1,
            outcome: Some(StrictTerminalOutcome::Commit(StrictDecisionCommit {
                ts_final: 75,
                op_msgpack: Bytes::from(rmp_serde::to_vec(&175u64).unwrap()),
            })),
            resolver_node: 0,
            resolver_boot_epoch: 0,
            frozen_targets: Vec::new(),
        };
        assert!(
            rt.apply_catchup_terminal_commit_with_repository_base(terminal.clone(), 100)
                .await
        );
        assert!(rt.repository_base_required());

        assert!(rt.finish_repository_base_install(100));
        assert!(!rt.repository_base_required());
        assert!(
            rt.apply_catchup_terminal_commit_with_repository_base(terminal, 90)
                .await
        );

        assert_eq!(
            rt.terminal_journal
                .lock()
                .await
                .get(op_id)
                .and_then(TerminalJournalRecord::required_repository_base_version),
            Some(100)
        );
        assert!(
            rt.repository_base_required(),
            "the already-durable record's stronger base must remain fenced"
        );
        assert!(
            !rt.state.lock().commit_buffer.contains_key(&(75, op_id)),
            "the commit must not enter delivery below its durable base"
        );
    }

    #[tokio::test]
    async fn terminal_journal_reloads_and_catchup_replays_fences() {
        let temp = tempfile::TempDir::new().unwrap();
        let source_net = MockNet::new(1, vec![1, 2]);
        source_net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        source_net.set_strict_protocol_state_dir(Some(temp.path().to_path_buf()));
        let abort_id = make_op_id(1, 1, 8);
        let commit_id = make_op_id(1, 1, 9);
        let commit_bytes = Bytes::from(rmp_serde::to_vec(&123u64).unwrap());
        {
            let source = StrictRuntime::new(
                CountingStrictRepo::new(),
                1,
                1,
                "channels".to_owned(),
                source_net.clone(),
                CancellationToken::new(),
                Arc::new(ReplicationConfig::default()),
            );
            assert!(source.apply_terminal_abort(abort_id, 8).await);
            assert!(
                source
                    .apply_terminal_commit(commit_id, 9, 12, commit_bytes.clone())
                    .await
            );
        }

        let source = StrictRuntime::new(
            CountingStrictRepo::new(),
            1,
            1,
            "channels".to_owned(),
            source_net,
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        let terminal_states = source.terminal_states_for_catchup().await;
        assert_eq!(terminal_states.len(), 2);
        assert!(matches!(
            source.state.lock().terminal_decisions.get(&abort_id),
            Some(TerminalDecision::Abort { .. })
        ));
        assert!(matches!(
            source.state.lock().terminal_decisions.get(&commit_id),
            Some(TerminalDecision::Commit(value))
                if value.ts_final == 12 && value.op_msgpack == commit_bytes
        ));

        let sink_net = MockNet::new(2, vec![1, 2]);
        sink_net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        let sink = StrictRuntime::new(
            CountingStrictRepo::new(),
            2,
            2,
            "channels".to_owned(),
            sink_net,
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        sink.recv_catchup_resp(
            1,
            StrictCatchupResp {
                snapshot_version: 0,
                snapshot_msgpack: Bytes::new(),
                ops: Vec::new(),
                terminal_states,
                next_terminal_state_cursor: 0,
                terminal_states_has_more: false,
                terminal_sync_only: false,
                request_force_snapshot: false,
                request_history_probe_only: false,
                terminal_decision_generation: 0,
                snapshot_transfer_id: 0,
                snapshot_chunk_cursor: 0,
                snapshot_next_cursor: 0,
                snapshot_total_bytes: 0,
                snapshot_sha256: Bytes::new(),
                snapshot_has_more: false,
                snapshot_transfer_rejected: false,
                has_more: false,
                next_chunk_token: 0,
                too_old_use_snapshot: false,
                history_version: 0,
                history_freshness: 0,
                runtime_started_at: 1,
                history_node: 1,
                history_transfer: None,
            },
        )
        .await;
        assert!(matches!(
            sink.state.lock().terminal_decisions.get(&abort_id),
            Some(TerminalDecision::Abort { .. })
        ));
        assert!(matches!(
            sink.state.lock().terminal_decisions.get(&commit_id),
            Some(TerminalDecision::Commit(value))
                if value.ts_final == 12 && value.op_msgpack == commit_bytes
        ));

        sink.recv_commit(
            1,
            StrictCommit {
                coord_node: 1,
                op_id_hi: abort_id.0,
                op_id_lo: abort_id.1,
                ts_final: 20,
                op_msgpack: Bytes::from(rmp_serde::to_vec(&999u64).unwrap()),
                src_clock: 20,
            },
        )
        .await;
        assert!(!sink.state.lock().committed_ids.contains(&abort_id));
    }

