    #[tokio::test]
    async fn terminal_catchup_pages_use_a_stable_snapshot_across_new_decisions() {
        let (runtime, _net, _repo) =
            v1_runtime(ReplicationConfig::default().with_strict_max_catchup_ops(1));
        let first = make_op_id(1, 1, 1);
        let third = make_op_id(1, 1, 3);
        assert!(runtime.apply_terminal_abort(first, 1).await);
        assert!(runtime.apply_terminal_abort(third, 1).await);

        let first_page = runtime
            .terminal_states_for_catchup_page(2, 0, 1, usize::MAX)
            .await;
        assert_eq!(first_page.states.len(), 1);
        assert_eq!(first_page.states[0].op_id_lo, 1);
        assert!(first_page.has_more);

        // This record sorts before the cursor in the live BTreeMap. A
        // transfer using the live index would resend or skip a terminal
        // fence; the existing peer snapshot must continue with `third`.
        let second = make_op_id(1, 1, 2);
        assert!(runtime.apply_terminal_abort(second, 1).await);
        let second_page = runtime
            .terminal_states_for_catchup_page(2, first_page.next_cursor, 1, usize::MAX)
            .await;
        assert_eq!(second_page.states.len(), 1);
        assert_eq!(second_page.states[0].op_id_lo, 3);
        assert!(!second_page.has_more);

        runtime.acknowledge_terminal_catchup_snapshot(
            2,
            second_page.terminal_decision_generation.wrapping_add(1),
        );
        let replayed = runtime
            .terminal_states_for_catchup_page(2, 0, usize::MAX, usize::MAX)
            .await;
        let replayed_ids: Vec<_> = replayed.states.iter().map(|state| state.op_id_lo).collect();
        assert_eq!(replayed_ids, vec![1, 3]);

        // A later sync starts a fresh snapshot and picks up the concurrent
        // terminal fence only after the requester acknowledges the completed
        // cut. Until then, duplicate final requests must replay that cut.
        runtime.acknowledge_terminal_catchup_snapshot(2, second_page.terminal_decision_generation);
        let refreshed = runtime
            .terminal_states_for_catchup_page(2, 0, usize::MAX, usize::MAX)
            .await;
        let ids: Vec<_> = refreshed
            .states
            .iter()
            .map(|state| state.op_id_lo)
            .collect();
        assert_eq!(ids, vec![1, 2, 3]);
    }

    #[tokio::test]
    async fn terminal_catchup_later_pages_reuse_the_peer_snapshot_without_resnapshotting() {
        let (runtime, _net, _repo) =
            v1_runtime(ReplicationConfig::default().with_strict_max_catchup_ops(1));
        let first = make_op_id(1, 1, 1);
        let second = make_op_id(1, 1, 2);
        assert!(runtime.apply_terminal_abort(first, 1).await);
        assert!(runtime.apply_terminal_abort(second, 1).await);

        let first_page = runtime
            .terminal_states_for_catchup_page(2, 0, 1, usize::MAX)
            .await;
        assert_eq!(first_page.states.len(), 1);
        assert!(first_page.has_more);

        super::super::terminal_journal::take_terminal_journal_snapshot_count();
        let continuation = {
            let _journal_guard = runtime.terminal_journal.lock().await;
            let runtime = Arc::clone(&runtime);
            let cursor = first_page.next_cursor;
            let continuation = tokio::spawn(async move {
                runtime
                    .terminal_states_for_catchup_page(2, cursor, 1, usize::MAX)
                    .await
            });
            tokio::task::yield_now().await;
            assert!(
                !continuation.is_finished(),
                "cached continuation must stay serialized behind terminal journal updates"
            );
            continuation
        };
        let second_page = tokio::time::timeout(Duration::from_millis(100), continuation)
            .await
            .expect("cached continuation must complete after the journal lock is released")
            .expect("cached continuation task must not panic");
        assert_eq!(
            super::super::terminal_journal::take_terminal_journal_snapshot_count(),
            0,
            "cached continuation must not clone the terminal journal"
        );

        assert_eq!(second_page.states.len(), 1);
        assert_eq!(second_page.states[0].op_id_lo, 2);
        assert!(!second_page.has_more);
    }

    #[tokio::test]
    async fn terminal_catchup_bounds_promise_only_journal_scans() {
        let (runtime, _net, _repo) = v1_runtime(ReplicationConfig::default());
        let first_promise = make_op_id(1, 1, 21);
        let second_promise = make_op_id(1, 1, 22);
        let terminal = make_op_id(1, 1, 23);
        {
            let mut journal = runtime.terminal_journal.lock().await;
            journal.upsert_promise(first_promise, 1).unwrap();
            journal.upsert_promise(second_promise, 1).unwrap();
        }
        assert!(runtime.apply_terminal_abort(terminal, 1).await);

        let first_page = runtime
            .terminal_states_for_catchup_page(2, 0, 2, usize::MAX)
            .await;
        assert!(first_page.states.is_empty());
        assert_eq!(first_page.next_cursor, 2);
        assert!(first_page.has_more);

        let second_page = runtime
            .terminal_states_for_catchup_page(2, first_page.next_cursor, 2, usize::MAX)
            .await;
        assert_eq!(second_page.states.len(), 1);
        assert_eq!(second_page.states[0].op_id_lo, 23);
        assert!(!second_page.has_more);
    }

    #[tokio::test]
    async fn v1_inbound_is_rejected_without_repository_capability() {
        let net = MockNet::new(1, vec![1, 2]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        let runtime = StrictRuntime::new(
            CountingStrictRepo::new_legacy(),
            1,
            1,
            "channels".to_owned(),
            net.clone(),
            CancellationToken::new(),
            Arc::new(ReplicationConfig::default()),
        );
        let op_id = make_op_id(2, 1, 12);
        let op_msgpack = Bytes::from(rmp_serde::to_vec(&655u64).unwrap());

        runtime
            .recv_propose_v1(
                2,
                StrictProposeV1 {
                    coord_node: 2,
                    op_id_hi: op_id.0,
                    op_id_lo: op_id.1,
                    ts_propose: 12,
                    op_msgpack: op_msgpack.clone(),
                    src_clock: 12,
                    protocol_version: STRICT_PROTOCOL_VERSION_V1,
                    frozen_targets: Vec::new(),
                },
            )
            .await;
        assert!(!runtime.state.lock().pending_proposes.contains_key(&op_id));

        runtime
            .recv_accept(
                2,
                StrictAccept {
                    coord_node: 2,
                    ballot: NORMAL_ACCEPT_BALLOT,
                    op_id_hi: op_id.0,
                    op_id_lo: op_id.1,
                    ts_final: 13,
                    op_msgpack,
                    src_clock: 13,
                },
            )
            .await;

        assert!(runtime.state.lock().accepted_values.get(&op_id).is_none());
        assert!(net.drain_captures().is_empty());
    }

    #[tokio::test]
    async fn v2_accepted_value_is_reconstructed_as_stale_pending_after_restart() {
        let temp = tempfile::TempDir::new().unwrap();
        let cfg = ReplicationConfig::default();
        let op_id = make_op_id(2, 1, 10);
        let op_msgpack = Bytes::from(rmp_serde::to_vec(&456u64).unwrap());
        let net = MockNet::new(1, vec![1, 2]);
        net.set_epoch(1, 1);
        net.set_epoch(2, 1);
        net.set_live_reliable_routes([1, 2]);
        net.set_strict_replication_protocol_version(STRICT_PROTOCOL_VERSION_V8);
        net.set_strict_protocol_state_dir(Some(temp.path().to_path_buf()));
        {
            let rt = StrictRuntime::new(
                CountingStrictRepo::new(),
                1,
                1,
                "channels".to_owned(),
                net.clone(),
                CancellationToken::new(),
                Arc::new(cfg.clone()),
            );
            rt.finish_history_election_for_test();
            {
                let mut state = rt.state.lock();
                state.admission_tracking_started = true;
                state.begin_peer_admission(2, 1);
                state
                    .peer_admissions
                    .get_mut(&2)
                    .expect("peer admission exists")
                    .phase = PeerAdmissionPhase::Admitted;
            }
            rt.recv_propose_v1(
                2,
                StrictProposeV1 {
                    coord_node: 2,
                    op_id_hi: op_id.0,
                    op_id_lo: op_id.1,
                    ts_propose: 10,
                    op_msgpack: op_msgpack.clone(),
                    src_clock: 10,
                    protocol_version: STRICT_PROTOCOL_VERSION_V2,
                    frozen_targets: v2_frozen_targets_wire(),
                },
            )
            .await;
            assert!(
                rt.state.lock().pending_proposes.contains_key(&op_id),
                "admitted v2 proposal must be retained before restart"
            );
            rt.recv_accept(
                2,
                StrictAccept {
                    coord_node: 2,
                    ballot: NORMAL_ACCEPT_BALLOT,
                    op_id_hi: op_id.0,
                    op_id_lo: op_id.1,
                    ts_final: 12,
                    op_msgpack: op_msgpack.clone(),
                    src_clock: 12,
                },
            )
            .await;
            assert!(
                rt.state.lock().accepted_values.contains_key(&op_id),
                "v2 accepted value must reach the durable restart source"
            );
            {
                let journal = rt.terminal_journal.lock().await;
                let record = journal.get(op_id).expect("v2 journal record");
                assert!(record.frozen_targets().is_some(), "descriptor must persist");
                assert!(record.accepted_commit().is_some(), "accept must persist");
            }
            rt.shutdown.cancel();
            tokio::time::timeout(Duration::from_secs(1), async {
                while Arc::strong_count(&rt) > 1 {
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("accept ACK retry worker must release the runtime on shutdown");
        }

        let recovered = StrictRuntime::new(
            CountingStrictRepo::new(),
            1,
            1,
            "channels".to_owned(),
            net.clone(),
            CancellationToken::new(),
            Arc::new(cfg.clone()),
        );
        recovered.finish_history_election_for_test();
        assert!(
            recovered.state.lock().accepted_values.contains_key(&op_id),
            "accepted value must reload before pending reconstruction"
        );
        assert!(matches!(
            recovered.state.lock().pending_proposes.get(&op_id),
            Some(PendingPropose { protocol_version, .. })
                if *protocol_version == STRICT_PROTOCOL_VERSION_V2
        ));
        recovered
            .state
            .lock()
            .pending_proposes
            .get_mut(&op_id)
            .expect("restarted v2 pending entry must be restored")
            .seen_at = Instant::now() - cfg.pending_propose_ttl() - Duration::from_millis(1);

        resolve_stale_with_remote_ack(&recovered, &net, op_id, 2, None).await;
        assert!(matches!(
            recovered.state.lock().terminal_decisions.get(&op_id),
            Some(TerminalDecision::Commit(value))
                if value.ts_final == 12 && value.op_msgpack == op_msgpack
        ));
    }
